// --- Sdilene casove funkce, ulozene do global kontextu pri startu ---
// Zona trhu (viz ZONY v build_flow.py): kod, casove pasmo a mena. Neznama / chybejici = CZ.
var FVE_ZONY = {"CZ":{"tz":"Europe/Prague","mena":"CZK"},"AT":{"tz":"Europe/Vienna","mena":"EUR"},"BE":{"tz":"Europe/Brussels","mena":"EUR"},"CH":{"tz":"Europe/Zurich","mena":"EUR"},"DE-LU":{"tz":"Europe/Berlin","mena":"EUR"},"DK1":{"tz":"Europe/Copenhagen","mena":"EUR"},"DK2":{"tz":"Europe/Copenhagen","mena":"EUR"},"EE":{"tz":"Europe/Tallinn","mena":"EUR"},"ES":{"tz":"Europe/Madrid","mena":"EUR"},"FI":{"tz":"Europe/Helsinki","mena":"EUR"},"FR":{"tz":"Europe/Paris","mena":"EUR"},"GR":{"tz":"Europe/Athens","mena":"EUR"},"HR":{"tz":"Europe/Zagreb","mena":"EUR"},"HU":{"tz":"Europe/Budapest","mena":"EUR"},"IT-North":{"tz":"Europe/Rome","mena":"EUR"},"IT-Centre-North":{"tz":"Europe/Rome","mena":"EUR"},"IT-Centre-South":{"tz":"Europe/Rome","mena":"EUR"},"IT-South":{"tz":"Europe/Rome","mena":"EUR"},"IT-Calabria":{"tz":"Europe/Rome","mena":"EUR"},"IT-Sicily":{"tz":"Europe/Rome","mena":"EUR"},"IT-Sardinia":{"tz":"Europe/Rome","mena":"EUR"},"LT":{"tz":"Europe/Vilnius","mena":"EUR"},"LV":{"tz":"Europe/Riga","mena":"EUR"},"NL":{"tz":"Europe/Amsterdam","mena":"EUR"},"NO1":{"tz":"Europe/Oslo","mena":"EUR"},"NO2":{"tz":"Europe/Oslo","mena":"EUR"},"NO3":{"tz":"Europe/Oslo","mena":"EUR"},"NO4":{"tz":"Europe/Oslo","mena":"EUR"},"NO5":{"tz":"Europe/Oslo","mena":"EUR"},"PL":{"tz":"Europe/Warsaw","mena":"EUR"},"PT":{"tz":"Europe/Lisbon","mena":"EUR"},"RO":{"tz":"Europe/Bucharest","mena":"EUR"},"RS":{"tz":"Europe/Belgrade","mena":"EUR"},"SE1":{"tz":"Europe/Stockholm","mena":"EUR"},"SE2":{"tz":"Europe/Stockholm","mena":"EUR"},"SE3":{"tz":"Europe/Stockholm","mena":"EUR"},"SE4":{"tz":"Europe/Stockholm","mena":"EUR"},"SI":{"tz":"Europe/Ljubljana","mena":"EUR"},"SK":{"tz":"Europe/Bratislava","mena":"EUR"},"BG":{"tz":"Europe/Sofia","mena":"EUR"}};
function fveZona() {
    var cfg = global.get('config') || {};
    var kod = FVE_ZONY[cfg.marketZone] ? cfg.marketZone : 'CZ';
    return { kod: kod, tz: FVE_ZONY[kod].tz, mena: FVE_ZONY[kod].mena };
}

// Mena pro zobrazeni: kod, jednotka a pocet desetinnych mist (EUR/kWh potrebuje 3: 0,085).
// Anglicka varianta flow pise misto 'Kc' 'CZK' (i18n/en.json, _nahrady).
function fveMena() {
    var eur = fveZona().mena === 'EUR';
    return { kod: eur ? 'EUR' : 'CZK', text: eur ? 'EUR' : 'Kc', des: eur ? 3 : 2 };
}

// Mistni den a minuta dne casove znacky (unix sekundy) v pasmu zony - pro prevod cen z API,
// ktere posila casy v UTC. hourCycle h23: nektere verze Node vraci pri hour12:false o pulnoci "24".
var _fveFmt = {};
function fveLokal(sec, tz) {
    tz = tz || fveZona().tz;
    if (!_fveFmt[tz]) _fveFmt[tz] = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hourCycle: 'h23',
        year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
    var p = {};
    _fveFmt[tz].formatToParts(new Date(sec * 1000)).forEach(function (x) { p[x.type] = x.value; });
    return { iso: p.year + '-' + p.month + '-' + p.day,
             minutesOfDay: (parseInt(p.hour, 10) % 24) * 60 + parseInt(p.minute, 10) };
}

function fveNow() {
    var tz = fveZona().tz;
    var d = new Date();
    var parts = new Intl.DateTimeFormat('en-GB', {
        timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false,
        weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric'
    }).formatToParts(d);
    var get = function (t) { return parts.find(function (p) { return p.type === t; }).value; };
    var dowMap = { Mon: 'mon', Tue: 'tue', Wed: 'wed', Thu: 'thu', Fri: 'fri', Sat: 'sat', Sun: 'sun' };
    var hh = parseInt(get('hour'), 10), mm = parseInt(get('minute'), 10);
    return {
        hm: (hh < 10 ? '0' + hh : hh) + ':' + (mm < 10 ? '0' + mm : mm),
        dow: dowMap[get('weekday')],
        minutesOfDay: hh * 60 + mm,
        iso: get('year') + '-' + get('month') + '-' + get('day')
    };
}

// Prevede casovy udaj na minuty od pulnoci. Tolerantne: "6", "6:00" i "06:00" dá 360; "24:00"
// dá 1440. Vraci null, kdyz se hodnota precist neda.
//
// POZOR, tohle neni kosmetika. Drive se cas parsoval jako 's.split(":").map(Number)', takze
// ulozene "6" (bez minut) dalo NaN. Porovnani 'f <= tt' je s NaN VZDY nepravdive, takze se tiše
// pouzila vetev "okno pres pulnoc" - a okno 6:00-10:00 se chovalo jako 00:00-10:00, bez jedine
// hlasky. Stejnou cestou dostal planovac ranniho odkladu 40 ctvrthodin misto 16. Proto se
// neplatny udaj radeji prizna (null) nez aby se mlcky preznacil.
function fveToMin(hm) {
    var m = /^(\d{1,2})(?::(\d{1,2}))?$/.exec(String(hm == null ? '' : hm).trim());
    if (!m) return null;
    var h = Number(m[1]), mi = m[2] ? Number(m[2]) : 0;
    if (h > 24 || mi > 59 || (h === 24 && mi > 0)) return null;
    return h * 60 + mi;
}

function fveInWindow(hm, from, to) {
    var t = fveToMin(hm), f = fveToMin(from), tt = fveToMin(to);
    if (t == null || f == null || tt == null) return false;   // neplatne okno neplati nikdy
    if (f <= tt) return t >= f && t < tt;
    return t >= f || t < tt; // pres pulnoc
}

// Spot je jen burzovni cena. Koncova cena, podle ktere se rozhoduje, je spot PLUS poplatky
// za nakup (distribuce, dan, obchodnik) a spot MINUS poplatek za prodej. Prepocet je schvalne
// na jednom miste - pouziva ho t_eval, planovac, oba percentilove helpery i graf, a kdyby to
// kazdy pocital po svem, hrozilo by porovnavani ciste ceny proti hrubemu spotu.
// Na FIXNI ceny se poplatky nevztahuji - ta se zadava rovnou jako koncova.
function fveNetBuy(spot) {
    if (spot == null) return null;
    var cfg = global.get('config') || {};
    var st = global.get('state') || {};
    // Poplatek k nakupu se lisi podle distribucniho tarifu. Ktery zrovna plati, urcuje tydenni
    // rozvrh na strance Tarify a ceny - dopocitava ho t_eval do st.tariff jeste driv, nez z nej
    // spocita nakupni cenu. Kdyz stav jeste neexistuje (prvni sekundy po startu), bereme VT,
    // protoze je drazsi, takze se spis nenakoupi, nez aby se nakoupilo za spatny predpoklad.
    var fee = (st.tariff === 'low') ? cfg.buyFeeNtPerKWh : cfg.buyFeeVtPerKWh;
    return spot + (fee || 0);
}

function fveNetSell(spot) {
    if (spot == null) return null;
    var cfg = global.get('config') || {};
    return spot - (cfg.sellFeePerKWh || 0);
}

// Rocni obdobi bud rucne prepinacem, nebo automaticky podle data - aby to uzivatel nemusel
// dvakrat rocne resit. Meze se zadavaji jako "MM-DD" a rozsah smi prechazet pres novy rok
// (typicky 11-15 az 02-28), proto ta dvojí varianta porovnani. Retezcove porovnani "MM-DD"
// funguje spravne, protoze obe casti maji pevnou sirku.
// Vsechny vetve, ktere se ptaly na cfg.season, se ptaji tady - jinak by rucni prepinac
// a automatika mohly kazda tvrdit neco jineho.
function fveSeason() {
    var cfg = global.get('config') || {};
    if (!cfg.seasonAuto) return cfg.season === 'winter' ? 'winter' : 'summer';
    var md = fveNow().iso.substring(5);          // "MM-DD"
    var from = cfg.winterFrom || '11-15';
    var to = cfg.winterTo || '02-28';
    var isWinter = (from <= to) ? (md >= from && md <= to) : (md >= from || md <= to);
    return isWinter ? 'winter' : 'summer';
}

// PLATNE NASTAVENI: spolecne hodnoty + profil prave platneho obdobi (cfg.summer / cfg.winter).
// Od 0.9.037 ma leto a zima kazde vlastni nastaveni prodeje, rezervy, klidoveho setpointu
// a nabijeni ze site. Regulace cte hodnoty vyhradne pres tuhle funkci, takze se o obdobi
// nemusi starat - klice v profilu maji stejne nazvy jako drive v plochem configu.
function fveCfg() {
    var cfg = global.get('config') || {};
    var p = cfg[fveSeason()];
    return (p && typeof p === 'object') ? Object.assign({}, cfg, p) : cfg;
}

// Prevod konfigurace ze starsich verzi (ploche klice) do profilu leto/zima. Pouziva ho nacteni
// configu pri startu i obnova ze zalohy. Obe profily dostanou dosavadni hodnoty, takze se chovani
// po aktualizaci nezmeni; jen vypnute "Obchodovat v zime" se stane "Nikdy nevybijet" v zime
// a nutne SOC v lete je 0 (drive se v lete ze site nenabijelo vubec).
function fveMigrujProfily(c, def) {
    if (!c || typeof c !== 'object') return false;
    var SPOL = ['exportPriceThreshold', 'batteryFullSocPercent', 'neverDischargeToGrid', 'batteryReservePercent',
                'exportSocThreshold', 'batteryTradingPercent', 'exportBMinPrice'];
    var STARE = SPOL.concat(['idleSetpointW', 'idleSetpointWinterW', 'winterTradingEnabled', 'winterMinSocPercent',
                'winterMinSocBy', 'winterNightTargetSocPercent', 'winterTargetBy', 'nightChargeMaxPrice',
                'winterNegativePriceCharge']);
    if (!STARE.some(function (k) { return k in c; })) return false;
    var s = Object.assign({}, (def && def.summer) || {}, c.summer || {});
    var w = Object.assign({}, (def && def.winter) || {}, c.winter || {});
    SPOL.forEach(function (k) { if (k in c) { s[k] = c[k]; w[k] = c[k]; } });
    if ('idleSetpointW' in c) { s.idleSetpointW = c.idleSetpointW; w.idleSetpointW = c.idleSetpointW; }
    if ('idleSetpointWinterW' in c) w.idleSetpointW = c.idleSetpointWinterW;
    if (c.winterTradingEnabled === false) w.neverDischargeToGrid = true;
    if ('winterMinSocPercent' in c) w.minSocPercent = c.winterMinSocPercent;
    if ('winterMinSocBy' in c) { w.minSocBy = c.winterMinSocBy; s.minSocBy = c.winterMinSocBy; }
    if ('winterNightTargetSocPercent' in c) w.targetSocPercent = c.winterNightTargetSocPercent;
    if ('winterTargetBy' in c) w.targetBy = c.winterTargetBy;
    if ('nightChargeMaxPrice' in c) w.targetMaxPrice = c.nightChargeMaxPrice;
    if ('winterNegativePriceCharge' in c) w.negativePriceCharge = c.winterNegativePriceCharge;
    STARE.forEach(function (k) { delete c[k]; });
    c.summer = s;
    c.winter = w;
    return true;
}

// Prevod ctvrthodinovych cen dne (v poradi, jak jdou za sebou) na 96 hodnot podle MISTNIHO casu.
// Dny zmeny casu nemaji 96 ctvrthodin: podzimni ma 100 (02:00-03:00 probehne dvakrat - vezme se
// prumer obou cen), jarni 92 (02:00-03:00 neexistuje - doplni se cenou 03:00-04:00, at v poli
// nejsou diry). Bez toho by se ceny po 02:00 posunuly o hodinu.
function fveNa96(v) {
    if (!Array.isArray(v)) return null;
    var out = new Array(96).fill(null), i;
    function prum(a, b) { return (a != null && b != null) ? (a + b) / 2 : (a != null ? a : b); }
    if (v.length === 100) {
        for (i = 0; i < 96; i++) out[i] = (i < 8) ? v[i] : (i < 12 ? prum(v[i], v[i + 4]) : v[i + 4]);
    } else if (v.length === 92) {
        for (i = 0; i < 96; i++) out[i] = (i < 12) ? v[i] : v[i - 4];
    } else {
        for (i = 0; i < 96 && i < v.length; i++) out[i] = v[i];
    }
    return out;
}

// Kody duvodu regulace ('nabijeni-ze-site'...) se v logice porovnavaji, takze se neprekladaji.
// Pro zobrazeni (Prehled, mobilni aplikace) je anglicka varianta flow prevede pres tuto tabulku -
// v ceske je prazdna (i18n/en.json, "_nahrady").
var FVE_KODY = {};
function fveKody(t) {
    if (typeof t !== 'string') return t;
    return t.replace(/[A-Za-z]+(?:-[A-Za-z]+)+/g, function (k) { return FVE_KODY[k] || k; });
}

function fveIsCheapNow() {
    var cfg = global.get('config') || {};
    var st = global.get('state') || {};
    if (st.tariff === 'low') return true;
    if (cfg.buyPriceType === 'spot' && st.currentBuyPrice != null) {
        var sp = global.get('spotPrices') || {};
        var arr = (sp.today || []).filter(function (v) { return v != null; });
        if (arr.length) {
            var sorted = arr.slice().sort(function (a, b) { return a - b; });
            // Percentil se prepocita stejnym prevodem jako aktualni cena, jinak by se porovnavala
            // ciste cena (spot + poplatek) proti hrubemu spotu.
            var p30 = fveNetBuy(sorted[Math.floor(sorted.length * 0.3)]);
            return st.currentBuyPrice <= p30;
        }
    }
    return false;
}

// Relativni cenove kriterium pro ranni odklad (mechanismus C). Zrcadlo fveIsExpensiveNow, ale
// pocitane JEN pres okno C - jde o to, jestli je ted nejdrazsi cast RANA, ne celeho dne.
// Duvod je stejny jako u mechanismu A: pevne cislo neveme nic o tom, jak drahy je zrovna den.
// Na drahem rane vycisti pevny prah kazda ctvrthodina, na levnem zadna, a po zavedeni poplatku
// se to jeste posunulo (currentBuyPrice = spot + poplatek, zatimco default 3,50 byl proti spotu).
// Vraci null, kdyz nejsou spotova data - pak plati jen pevna podlaha, stejne jako u A.
function fveMorningPrice() {
    var cfg = global.get('config') || {};
    var st = global.get('state') || {};
    var md = cfg.morningDeferral || {};
    var sp = global.get('spotPrices') || {};

    // Od 0.9.031 se ranni odklad ridi PRODEJNI cenou (spot minus poplatek za prodej). Odklad
    // posila ranni prebytek do site misto do baterie, takze rozhoduje, kolik za tu energii
    // dostanu - ne kolik bych platil za nakup. Do 0.9.030 se tu omylem bral nakup: u zakaznika
    // s fixnim nakupem a spotovym prodejem byla podminka splnena vzdy a odklad by dodaval i pri
    // nizkem nebo zapornem rannim spotu.
    // Pri FIXNI prodejni cene relativni kriterium nema smysl (zadna "drazsi cast rana"
    // neexistuje) a porovnavat konstantu proti kvartilu ze spotu by byla dve ruzna meritka.
    if (cfg.sellPriceType !== 'spot') return { fixed: true, ok: true };

    if (!sp.today) return null;
    var mFrom = fveToMin(md.from || '06:00');
    var mTo = fveToMin(md.to || '10:00');
    if (mFrom == null || mTo == null) return null;   // neplatne okno - radeji nic nez spatna ctvrtina
    var qFrom = Math.floor(mFrom / 15);
    var qTo = Math.ceil(mTo / 15);
    var idx = [];
    if (qFrom <= qTo) {
        for (var a = qFrom; a < qTo; a++) idx.push(a);
    } else {                       // okno pres pulnoc (nerealne, ale at to nespadne)
        for (var b = qFrom; b < 96; b++) idx.push(b);
        for (var c = 0; c < qTo; c++) idx.push(c);
    }
    var ceny = [];
    for (var k = 0; k < idx.length; k++) {
        var v = sp.today[idx[k]];
        if (v != null) ceny.push(fveNetSell(v));
    }
    if (ceny.length < 4) return null;
    var sorted = ceny.slice().sort(function (x, y) { return x - y; });
    var p75 = sorted[Math.floor(sorted.length * 0.75)];
    var kolik = ceny.filter(function (q) { return q >= p75; }).length;
    return {
        quartile: p75,
        pocetOken: kolik,
        celkemOken: ceny.length,
        ok: (st.currentSellPrice != null && st.currentSellPrice >= p75)
    };
}

// Zrcadlovy protejsek fveIsCheapNow pro mechanismus A (kap. 5A). Fixni cenovy prah sam o sobe
// nestaci: v drahych dnech je NAD prahem uplne kazda ctvrthodina (overeno na zivych datech -
// 3,31 az 5,43 Kc/kWh pri prahu 2,5), takze by se baterie vyprodala uz v noci a rano by se
// stejna energie kupovala zpatky draz. Proto jeste vyzadujeme, aby cena patrila do horni
// ctvrtiny dneska. Vraci null, kdyz spotova data nejsou k dispozici - volajici si pak rozhodne
// sam (v ex_decide se v takovem pripade jede jen podle fixniho prahu).
function fveIsExpensiveNow() {
    var cfg = global.get('config') || {};
    var st = global.get('state') || {};
    // Stejny duvod jako u fveMorningPrice: pri fixni prodejni cene neexistuje "spicka dne", takze
    // se smi uplatnit jen pevny cenovy prah. Bez teto podminky by se konstanta porovnavala
    // s kvartilem ze spotu a mechanismus A by se choval podle toho, jaky je zrovna den.
    if (cfg.sellPriceType !== 'spot') return null;
    if (st.currentSellPrice == null) return null;
    var sp = global.get('spotPrices') || {};
    var arr = (sp.today || []).filter(function (v) { return v != null; });
    if (arr.length < 4) return null;
    var sorted = arr.slice().sort(function (a, b) { return a - b; });
    // horni kvartil = hodnota, pod kterou lezi 75 % ctvrthodin dneska
    var p75 = fveNetSell(sorted[Math.floor(sorted.length * 0.75)]);
    return st.currentSellPrice >= p75;
}



global.set('fveNow', fveNow);
global.set('fveZona', fveZona);
global.set('fveMena', fveMena);
global.set('fveLokal', fveLokal);
global.set('fveInWindow', fveInWindow);
global.set('fveIsCheapNow', fveIsCheapNow);
global.set('fveIsExpensiveNow', fveIsExpensiveNow);
global.set('fveNetBuy', fveNetBuy);
global.set('fveNetSell', fveNetSell);
global.set('fveSeason', fveSeason);
global.set('fveMorningPrice', fveMorningPrice);
global.set('fveCfg', fveCfg);
global.set('fveMigrujProfily', fveMigrujProfily);
global.set('fveNa96', fveNa96);
global.set('fveKody', fveKody);


