var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveMigrujProfily = global.get('fveMigrujProfily');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');

var om = (global.get('config') || {}).openMeteo || {};
// Drive tu byl zalozni bod v Praze. U instalace bez vyplnenych souradnic by to davalo predpoved
// z uplne jineho mista, ktera vypada verohodne - radeji zadnou a jasne receno proc.
if (typeof om.latitude !== 'number' || typeof om.longitude !== 'number') {
    node.status({ fill: 'red', shape: 'ring', text: 'chybi souradnice (Konfigurace)' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: om.latitude + ', ' + om.longitude });
msg.url = 'https://api.open-meteo.com/v1/forecast?latitude=' + om.latitude + '&longitude=' + om.longitude +
          '&hourly=shortwave_radiation,terrestrial_radiation&forecast_days=4&timezone=' + encodeURIComponent(fveZona ? fveZona().tz : 'Europe/Prague');
return msg;

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

var cfg = global.get('config') || {};
var body = msg.payload || {};
var hourly = body.hourly || {};
var times = hourly.time || [];
var rad = hourly.shortwave_radiation || [];
var ext = hourly.terrestrial_radiation || [];

// Scitame KAZDY den zvlast. Dnesek potrebuje mechanismus C (pocasova brzda), zitrek nabijeni ze site,
// a kalibrace (od 0.9.040) vybira nejlepsi ze 3 dnu - proto se stahuji 4 dny (i vecer v 20:00
// pokryji dnesek + 3 dalsi).
var todayIso = fveNow().iso;
var dny = {};
for (var i = 0; i < times.length; i++) {
    var dateIso = times[i].substring(0, 10);
    if (!dny[dateIso]) dny[dateIso] = { sw: 0, terr: 0 };
    dny[dateIso].sw += (rad[i] || 0);     // hodinova data W/m2 ~ Wh/m2 za tu hodinu
    dny[dateIso].terr += (ext[i] || 0);   // extraterestricka radiace = cistá geometrie slunce
}

var perfRatio = 0.75;      // hruby koeficient ztrat (teplota, strida, orientace) - viz README
var stcIrradiance = 1000;  // W/m2 pri STC

// INDEX JASNOSTI = dopadla radiace / extraterestricka radiace, tedy zhruba 0,15 (huste zatazeno)
// az 0,75 (jasno). Proc prave tohle a ne kWh nebo oblacnost:
//   - je SEZONNE INVARIANTNI, protoze sklon slunce uz je ve jmenovateli (jasny leden a jasny
//     cerven daji podobne cislo, i kdyz se vyroba lisi nekolikanasobne),
//   - nezavisi na velikosti FVE ANI na koeficientu perfRatio - v podilu se vykrati,
//   - je to lepsi prediktor vyroby nez oblacnost (vysoka rida oblacnost skoro nestini).
// Diky tomu staci uzivateli nastavit prah jednou a plati cely rok.
function shrn(d) {
    if (!d) return { kWh: null, clearness: null };
    return {
        kWh: (d.sw / stcIrradiance) * (cfg.pvSizeKWp || 0) * perfRatio,
        clearness: (d.terr > 0) ? (d.sw / d.terr) : null
    };
}
var zitraIso = Object.keys(dny).filter(function (k) { return k !== todayIso; }).sort()[0] || null;
var dnes = shrn(dny[todayIso]);
var zitra = shrn(zitraIso ? dny[zitraIso] : null);

var st = global.get('state') || {};
st.pvPredictionTodayKWh = dnes.kWh;
st.pvClearnessToday = dnes.clearness;
st.pvPredictionTomorrowKWh = zitra.kWh;
st.pvClearnessTomorrow = zitra.clearness;
// Ke kteremu dni hodnoty patri. Po pulnoci je 'Today' z vecerniho stazeni ve skutecnosti vcerejsek
// a dnesek lezi v 'Tomorrow' - kalibrace se v noci rozhoduje podle dnesni predpovedi, takze musi
// vedet, kterou z nich vzit (viz cal_eval).
st.pvPredictionTodayIso = todayIso;
st.pvPredictionTomorrowIso = zitraIso;
st.pvPredictionAt = Date.now();
// Vsechny dny podle data (kalibrace si z nich vybira nejlepsi den).
var vsechny = {};
Object.keys(dny).forEach(function (k) { var x = shrn(dny[k]); vsechny[k] = { kWh: x.kWh, clearness: x.clearness }; });
st.pvForecastDays = vsechny;
global.set('state', st);

function fmt(x) { return (x == null) ? '?' : x.toFixed(1); }
function fmtI(x) { return (x == null) ? '?' : x.toFixed(2); }
node.status({ fill: 'green', shape: 'dot',
              text: 'dnes ' + fmt(dnes.kWh) + ' kWh (' + fmtI(dnes.clearness) + '), zitra '
                    + fmt(zitra.kWh) + ' kWh (' + fmtI(zitra.clearness) + ')' });
return { payload: { todayKWh: dnes.kWh, todayClearness: dnes.clearness,
                    tomorrowKWh: zitra.kWh, tomorrowClearness: zitra.clearness },
         topic: 'pv-prediction' };

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

// ZIMNI NABIJENI ZE SITE - tri hladiny, kazda vybrana ctvrthodina nese svuj cilovy SOC:
//  1) NUTNE SOC (minSocPercent, leto i zima) - nabije se VZDY, bez ohledu na cenu, nejpozdeji do
//     'minSocBy'. Bere nejlevnejsi ctvrthodiny od ted do toho casu. Neupravuje se podle
//     predpovedi - je to pojistka. Zaroven je to v zime dno pro prodej (A ani B pod nej neprodaji).
//  2) CILOVE SOC (targetSocPercent, JEN ZIMA) - jen v ctvrthodinach s cenou <= strop
//     (targetMaxPrice, 0 = bez stropu), nejpozdeji do 'targetBy'. Snizuje se podle
//     predpovedi FVE na den terminu (nejvys o 40 %) - co dodá slunce zdarma, nekupuje se.
//  3) ZAPORNA CENA (negativePriceCharge, leto i zima) - kazda znama ctvrthodina s koncovou nakupni cenou
//     pod nulou nabiji az na 100 %: za odber se plati tobe.
// Do 0.9.018 bylo pevne nocni okno 22:00-07:00 a jeden cil; levna odpoledne (typicky o vikendu)
// tak zustavala nevyuzita.
//
// Cena je KONCOVA vcetne poplatku podle tarifu dane ctvrthodiny. U fixni nakupni ceny se pocita
// fix + poplatek - do 0.9.018 se tu i pro fix bral spot, takze poradi oken nedavalo smysl.
// Plan se prepocitava kazdych 5 minut ze ZIVEHO SOC, takze se sam dorovnava.
var cfg = fveCfg();   // platny profil (leto/zima) + spolecne hodnoty
var st = global.get('state') || {};
var sp = global.get('spotPrices') || {};
var now = fveNow();
var nowIdx = Math.floor(now.minutesOfDay / 15);

function num(x, def) { return (typeof x === 'number' && isFinite(x)) ? x : def; }
function pad2(v) { return (v < 10 ? '0' : '') + v; }
function plusDny(iso, n) {
    var d = new Date(iso + 'T12:00:00');
    d.setDate(d.getDate() + n);
    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
}
function hmIdx(a) { var i = a % 96; return pad2(Math.floor(i / 4)) + ':' + pad2((i % 4) * 15); }

function uloz(plan, text, fill) {
    global.set('nightChargePlan', plan);
    node.status({ fill: fill || 'blue', shape: 'dot', text: text });
    return { payload: plan, topic: 'nightcharge-plan' };
}
function prazdny(text) {
    return uloz({ generatedAt: Date.now(), targets: {}, chosenKey: [], levels: null, note: text }, text, 'grey');
}

var zima = (fveSeason() === 'winter');
var capKWh = cfg.batteryCapacityKWh || 0;
if (st.soc == null || capKWh <= 0) return prazdny('chybi SOC nebo kapacita');
var chargeKW = (cfg.maxChargePowerKW != null) ? cfg.maxChargePowerKW : (cfg.nominalMaxFeedInPowerKW || 0);
var perSlotKWh = chargeKW * 0.25;
if (perSlotKWh <= 0) return prazdny('nulovy nabijeci vykon');

// Termin "dosahnout do" jako absolutni ctvrthodina od dnesni pulnoci (0-191): nejblizsi vyskyt
// v budoucnu. 06:00 ve 23:00 je tedy zitrejsi 06:00, v 05:00 dnesni.
function termin(hm, def) {
    var m = /^(\d{1,2}):(\d{2})$/.exec(String(hm || def));
    var idx = m ? (Number(m[1]) * 4 + Math.floor(Number(m[2]) / 15)) : 24;
    if (idx <= nowIdx) idx += 96;
    return idx;
}
var todayIso = now.iso;
var tomorrowIso = plusDny(todayIso, 1);
var DOWS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
var tomorrowDow = DOWS[(DOWS.indexOf(now.dow) + 1) % 7];

// Od 0.9.037: nutne SOC a zaporna cena plati v obou obdobich (kazde ma vlastni hodnoty v profilu),
// cilove SOC pri nizke cene jen v zime. Profil vraci fveCfg().
var minSoc = num(cfg.minSocPercent, 0);
var minBy = cfg.minSocBy || '06:00';
var minEnd = termin(minBy, '06:00');
var tgtBase = zima ? num(cfg.targetSocPercent, 0) : 0;
var tgtBy = cfg.targetBy || '06:00';
var tgtEnd = termin(tgtBy, '06:00');
var maxPrice = num(cfg.targetMaxPrice, 0);
var negOn = (cfg.negativePriceCharge === true);
if (minSoc <= 0 && tgtBase <= 0 && !negOn) return prazdny('nabijeni ze site vypnuto');

// Cilove SOC se snizi podle predpovedi FVE na DEN TERMINU (n_predict oznacuje predpoved datem).
var tgtIso = (tgtEnd >= 96) ? tomorrowIso : todayIso;
var pvKWh = (st.pvPredictionTodayIso === tgtIso) ? st.pvPredictionTodayKWh
          : (st.pvPredictionTomorrowIso === tgtIso) ? st.pvPredictionTomorrowKWh : null;
var adj = (pvKWh != null) ? Math.min(40, Math.max(0, pvKWh / capKWh * 100)) : 0;
var tgt = Math.min(100, Math.max(0, tgtBase - adj));

// Tarif a koncova cena pro KAZDOU ctvrthodinu zvlast.
function tarif(dowKey, i) {
    var sched = (cfg.tariffSchedule && cfg.tariffSchedule[dowKey]) || [];
    var hm = pad2(Math.floor(i / 4)) + ':' + pad2((i % 4) * 15);
    for (var k = 0; k < sched.length; k++) {
        if (sched[k].type === 'low' && fveInWindow(hm, sched[k].from, sched[k].to)) return 'low';
    }
    return 'high';
}
var fix = (cfg.buyPriceType === 'fix');
var dnesCeny = (sp.todayIso === todayIso) ? sp.today : null;
var zitraCeny = (sp.tomorrowIso === tomorrowIso) ? sp.tomorrow : null;
// Zaloha: kdyz spotove ceny na cely den chybi, pocita se s fixni nakupni cenou - stejne jako
// u aktualni ceny (t_eval). Do 0.9.044 se den bez cen preskocil, takze se nenaplanovalo ani
// NUTNE SOC (pojistka). Stalo se 25.10.2026: v den zmeny casu vratilo API prazdna data.
// Zitrejsi ceny se zverejnuji kolem 13-14 h, takze dopoledne zitrek bez cen je normalni stav -
// pro zitrek se zaloha pouzije az od 15:00, kdy uz ceny normalne maji byt.
var fixZaloha = num(cfg.fixBuyPrice, null);
var zitraZaloha = (now.minutesOfDay >= 15 * 60);
var zalozni = 0;

// Vsechny zname budouci ctvrthodiny (dnesek od ted + zitrek, pokud jsou ceny).
var sloty = [];
for (var a = nowIdx; a < 192; a++) {
    var zitra = (a >= 96), i = a % 96;
    var dowKey = zitra ? tomorrowDow : now.dow;
    var t = tarif(dowKey, i);
    var fee = (t === 'low') ? cfg.buyFeeNtPerKWh : cfg.buyFeeVtPerKWh;
    var zaklad;
    if (fix) {
        zaklad = num(cfg.fixBuyPrice, null);
    } else {
        var arr = zitra ? zitraCeny : dnesCeny;
        zaklad = arr ? arr[i] : ((zitra && !zitraZaloha) ? null : fixZaloha);
        if (!arr && zaklad != null) zalozni++;
    }
    if (zaklad == null) continue;
    sloty.push({ a: a, key: (zitra ? tomorrowIso : todayIso) + ':' + i, price: zaklad + (fee || 0), low: t === 'low' });
}
// Nejlevnejsi napred; pri shode (typicky fixni cena) nizky tarif, pak drivejsi.
function poradi(x, y) { return (x.price - y.price) || ((y.low ? 1 : 0) - (x.low ? 1 : 0)) || (x.a - y.a); }
function vyber(kandidati, needKWh) {
    var out = [], zbyva = needKWh;
    kandidati.slice().sort(poradi).forEach(function (s) { if (zbyva > 0) { out.push(s); zbyva -= perSlotKWh; } });
    return out;
}

var needMin = Math.max(0, (minSoc - st.soc) / 100 * capKWh);
var needTgt = Math.max(0, (tgt - st.soc) / 100 * capKWh);
var setMin = vyber(sloty.filter(function (s) { return s.a < minEnd; }), needMin);
var setTgt = vyber(sloty.filter(function (s) { return s.a < tgtEnd && (maxPrice <= 0 || s.price <= maxPrice); }), needTgt);
var setNeg = negOn ? sloty.filter(function (s) { return s.price < 0; }) : [];

var targets = {};
function pridej(set, soc) { set.forEach(function (s) { targets[s.key] = Math.max(targets[s.key] || 0, soc); }); }
pridej(setMin, minSoc);
pridej(setTgt, tgt);
pridej(setNeg, 100);

function prvni(set) { return set.length ? hmIdx(set.slice().sort(function (x, y) { return x.a - y.a; })[0].a) : null; }
var levels = {
    minSoc: minSoc, minBy: minBy, minNeedKWh: needMin, minSlots: setMin.length, minFirst: prvni(setMin),
    tgt: tgt, tgtBase: tgtBase, tgtBy: tgtBy, tgtNeedKWh: needTgt, tgtSlots: setTgt.length,
    tgtFirst: prvni(setTgt), maxPrice: maxPrice, pvAdj: adj,
    negSlots: setNeg.length, negFirst: prvni(setNeg),
    // Nutne SOC se nestihne, kdyz pred terminem neni dost ctvrthodin (nebo cen).
    minShortKWh: Math.max(0, needMin - setMin.length * perSlotKWh),
    // Kolik ctvrthodin se planovalo s fixni cenou, protoze spotove ceny chybely.
    fixFallbackSlots: zalozni
};
var keys = Object.keys(targets);
return uloz({ generatedAt: Date.now(), targets: targets, chosenKey: keys, levels: levels },
            'nutne ' + setMin.length + ', levne ' + setTgt.length + ', zaporne ' + setNeg.length
            + ' ctvrthodin (cil ' + tgt.toFixed(0) + ' %)' + (zalozni ? ' - bez spot cen, fixni cena' : ''),
            zalozni ? 'yellow' : 'blue');

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

// Nabiji se, kdyz je aktualni ctvrthodina v planu nb_plan a SOC je pod cilem TE ctvrthodiny
// (nutne SOC, cilove SOC nebo 100 % pri zaporne cene).
var cfg = fveCfg();   // platny profil (leto/zima) + spolecne hodnoty
var st = global.get('state') || {};
var now = fveNow();
var nowIdx = Math.floor(now.minutesOfDay / 15);
var season = fveSeason();

var plan = global.get('nightChargePlan') || {};
var cilTed = (plan.targets || {})[now.iso + ':' + nowIdx];
var active = cilTed != null && st.soc != null && st.soc < cilTed;

var minSoc = (typeof cfg.minSocPercent === 'number') ? cfg.minSocPercent : 0;
st.nightChargeActive = active;
st.nightChargeSlotTarget = active ? cilTed : null;
// Nutne SOC je DNO pro prodej: dokud je baterie pod nim, nevybiji ji A ani B (cte ex_decide).
// Od 0.9.037 v obou obdobich - kazde ma vlastni hodnotu (0 = bez nutneho SOC).
st.minSocFloor = minSoc > 0 ? minSoc : null;
st.nightChargeNeeded = minSoc > 0 && st.soc != null && st.soc < minSoc;
global.set('state', st);

return { payload: { active: active, target: cilTed, season: season, seasonAuto: !!cfg.seasonAuto, mode: cfg.mode || 'auto' },
         topic: 'night-charge-status' };

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

var st = global.get('state') || {};
var cal = st.calibration || { lastFullSocDate: null };
var prevDate = cal.lastFullSocDate;
if (typeof msg.payload === 'number' && msg.payload >= 100) {
    cal.lastFullSocDate = fveNow().iso;
}
st.calibration = cal;
global.set('state', st);

// Zapisovat na flash JEN pri skutecne zmene data. Tato funkce se vola pri kazde zmene SOC,
// takze bezpodminecny zapis by zbytecne opotreboval flash pamet GX zarizeni.
if (cal.lastFullSocDate === prevDate) {
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: '100% SOC: ' + cal.lastFullSocDate });
return { filename: '/data/home/nodered/.node-red/fve-flow-data/calibration-state.json', payload: JSON.stringify(cal, null, 2), topic: 'write-calibration' };

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

// Kalibrace = jednou za cas dojet na 100 %, aby si BMS srovnal odhad SOC. Od 0.9.040:
//  1) ZE SLUNCE (posledni 4 dny pred limitem, pri 14 dnech dny 10-13): rano 05:00-10:00 se
//     zkontroluje dnesni predpoved. Kdyz je jasno (index >= 0,5) a vyroba pokryje chybejici
//     energii (1x), vyhlasi se kalibracni den ze slunce: do 100 % (nebo do 17:00) nejedou A, B ani C,
//     klidovy setpoint je 0 a prebytek jde do baterie. Ze site se nenabiji.
//  2) KALIBRACNI REZIM (od 0.9.042, od limitu 'calibration.intervalDays' az do 100 %): nic se
//     neprodava (A, B, C stoji, klidovy setpoint 0), prebytek jde do baterie; do site tece jen to,
//     co baterie nepobere. Od casu 'calibration.topUpLatest' (vychozi 13:00) se baterie, jakmile
//     prekroci 'calibration.topUpFromSoc' (vychozi 95 %), ZE SITE DOBIJE do 100 % - v kterykoli den
//     rezimu. Pred 13:00 ne: za slunecneho dne by ji dobilo slunce zdarma.
//  3) KALIBRACNI DEN (pojistka, kdyz baterie na prah nedojde): ze 3 dnu od limitu se podle predpovedi
//     vybere ten s nejvetsi vyrobou (rozhoduje se o pulnoci kazdeho z nich: dnes, kdyz zadny ze
//     zbyvajicich neni lepsi; posledni je kalibracni vzdy). V nem se dobiji ze site do 100 % bez
//     ohledu na SOC i cenu - jakmile vyroba trvale klesne pod spotrebu (nejdriv 2 h pred
//     nastavenym casem), nejpozdeji v nastavenem case.
// Do 0.9.039 se po 14 dnech nabijelo ze site v kazdem levnem tarifu - typicky v noci poloprazdna
// baterie (25 kWh), zastavene uprostred koncem NT a dokoncovane po kouscich.
var st = global.get('state') || {};
var cfg = global.get('config') || {};
var cs = (global.get('configStatic') || {}).batteryCalibration || {};
var kc = cfg.calibration || {};
function num(x, d) { return (typeof x === 'number' && isFinite(x)) ? x : d; }
function hmMin(x) {
    var m = /^(\d{1,2}):(\d{2})$/.exec(String(x == null ? '' : x).trim());
    return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}
function hm(min) { return ('0' + Math.floor(min / 60)).slice(-2) + ':' + ('0' + (min % 60)).slice(-2); }
var interval = Math.max(3, Math.min(90, Math.round(num(kc.intervalDays, 14))));
var fromSoc = Math.max(50, Math.min(99, num(kc.topUpFromSoc, 95)));
var solarFrom = Math.max(1, interval - 4);
var KANDIDATU = 3;                       // kalibracni den = nejlepsi ze 3 dnu od limitu
var DEFICIT_MIN = 15;                    // jak dlouho musi byt vyroba pod spotrebou (min)
var minClear = num(cs.solarMinClearness, 0.5);
var reserve = num(cs.solarEnergyReserve, 1.0);
var decideUntil = hmMin(cs.solarDecideUntil) || 600;
var dayUntil = hmMin(cs.solarDayUntil) || 1020;
var latest = hmMin(kc.topUpLatest);
if (latest == null) latest = 13 * 60;
var earliest = Math.max(0, latest - 120);

var DNY = ['ne', 'po', 'ut', 'st', 'ct', 'pa', 'so'];
function dm(iso) { var p = iso.split('-'); return Number(p[2]) + '.' + Number(p[1]) + '.'; }
function den(iso) { return DNY[new Date(iso + 'T12:00:00').getDay()] + ' ' + dm(iso); }
function plusDny(iso, n) {
    var d = new Date(iso + 'T12:00:00');   // poledne: posun casu (letni/zimni) neprehodi den
    d.setDate(d.getDate() + n);
    return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2);
}
function vypni() {
    st.calSolarActive = false; st.calDayActive = false; st.calTopUpActive = false;
}

// Stav kalibrace jeste neni nacteny ze souboru (prvni sekundy po startu). Bez data nevime nic,
// a to NENI duvod nabijet - do 0.9.016 se to cetlo jako "pred 9999 dny".
var cal = st.calibration;
if (!cal || !cal.lastFullSocDate) {
    vypni();
    global.set('state', st);
    node.status({ fill: 'grey', shape: 'ring', text: 'ceka na nacteni stavu' });
    return [{ payload: { text: 'nacita se...' }, topic: 'calibration-status' }, null];
}

var now = fveNow();
var todayIso = now.iso;
var nowMin = now.minutesOfDay;
// Kalendarni dny (podle data), ne milisekundy/86400000 - den zmeny casu ma 23 nebo 25 hodin a
// vecer by se pak "9. den" pocital jako 10. (zjisteno 25.10.2026).
function isoDen(iso) { var p = String(iso).split('-'); return Date.UTC(+p[0], +p[1] - 1, +p[2]) / 86400000; }
var daysSince = isoDen(todayIso) - isoDen(cal.lastFullSocDate);
var dny = Math.max(0, Math.floor(daysSince));
var plna = (st.soc != null && st.soc >= 100);
var hotovoDnes = (cal.lastFullSocDate === todayIso);
var zapis = false;

// Kolik energie chybi do 100 %. Bez kapacity nebo SOC nelze posoudit, jestli slunce staci.
var capKWh = cfg.batteryCapacityKWh || 0;
var chybiKWh = (st.soc != null && capKWh > 0) ? capKWh * (100 - st.soc) / 100 : null;

// Predpoved pro konkretni den. pvForecastDays (od 0.9.040) ma vsechny stazene dny podle data;
// stara pole Today/Tomorrow jen jako zaloha.
function predpoved(iso) {
    var fd = st.pvForecastDays || {};
    if (fd[iso]) return { kWh: fd[iso].kWh, jas: fd[iso].clearness };
    if (st.pvPredictionTodayIso === iso) return { kWh: st.pvPredictionTodayKWh, jas: st.pvClearnessToday };
    if (st.pvPredictionTomorrowIso === iso) return { kWh: st.pvPredictionTomorrowKWh, jas: st.pvClearnessTomorrow };
    return null;
}
function dobryDen(iso) {
    var p = predpoved(iso);
    if (!p || p.kWh == null || p.jas == null || chybiKWh == null) return false;
    return p.jas >= minClear && p.kWh >= reserve * chybiKWh;
}

// --- 1) kalibracni den (od limitu) -------------------------------------------------------------
var dueIso = plusDny(cal.lastFullSocDate, interval);          // den, kdy uplyne interval
var lastIso = plusDny(dueIso, KANDIDATU - 1);                  // posledni ze 3 kandidatu
var naplanovano = null;
if (cal.calDay && cal.calDay < todayIso) { delete cal.calDay; zapis = true; }
if (!hotovoDnes && !plna && st.soc != null && todayIso >= dueIso && cal.calDay !== todayIso) {
    // Dnes, kdyz zadny ze zbyvajicich kandidatu nema vyrazne lepsi predpoved (o 0,5 kWh). Bez
    // predpovedi na dnesek neni podle ceho cekat - pak dnes. Po poslednim kandidatovi vzdy dnes.
    var nejlepsi = todayIso;
    var pd = predpoved(todayIso);
    var nejKWh = (pd && pd.kWh != null) ? pd.kWh : null;
    if (todayIso < lastIso && nejKWh != null) {
        for (var i = 1; plusDny(todayIso, i) <= lastIso; i++) {
            var iso = plusDny(todayIso, i), p = predpoved(iso);
            if (p && p.kWh != null && p.kWh > nejKWh + 0.5) { nejlepsi = iso; nejKWh = p.kWh; }
        }
    }
    if (nejlepsi === todayIso) {
        cal.calDay = todayIso;
        zapis = true;
        node.warn('Kalibrace: dnes kalibracni den (' + dny + ' dni bez 100 %, predpoved '
                  + (nejKWh != null ? nejKWh.toFixed(1) + ' kWh' : 'neni') + ').');
    } else {
        naplanovano = { iso: nejlepsi, kWh: nejKWh };
    }
}
// Kalibracni rezim: od limitu az do 100 % (vcetne cekacich dnu pred kalibracnim dnem).
var calMode = !hotovoDnes && !plna && st.soc != null && todayIso >= dueIso;
var calDay = calMode && (cal.calDay === todayIso);

// Dobiti ze site:
//  - kterykoli den rezimu: od nastaveneho casu, jakmile SOC prekroci prah (vychozi 95 %),
//  - kalibracni den: SOC je nejvyssi, kdyz vyroba klesne pod spotrebu (baterie by se zacala
//    vybijet) - nejdriv 2 h pred nastavenym casem, nejpozdeji v nem, pri jakemkoli SOC.
if (calMode) {
    if (typeof st.surplusPowerW === 'number' && st.surplusPowerW < 0) {
        if (!st.calDeficitSince) st.calDeficitSince = Date.now();
    } else {
        st.calDeficitSince = null;
    }
    var deficitMin = st.calDeficitSince ? (Date.now() - st.calDeficitSince) / 60000 : 0;
    var spoustec = null;
    if (nowMin >= latest && st.soc >= fromSoc) spoustec = 'SOC nad ' + fromSoc + ' %';
    else if (calDay && nowMin >= latest) spoustec = 'kalibracni den, nastaveny cas';
    else if (calDay && nowMin >= earliest && deficitMin >= DEFICIT_MIN) spoustec = 'kalibracni den, vyroba pod spotrebou';
    if (!st.calTopUp && spoustec) {
        st.calTopUp = true;
        st.calTopUpFrom = hm(nowMin);
        node.warn('Kalibrace: dobijim ze site na 100 % (SOC ' + Math.round(st.soc) + ' %, ' + spoustec + ').');
    }
    // Pojistka: nektere BMS na 100 % nikdy nedojdou (drzi treba 99 %). Kdyz pri dobijeni SOC
    // nad 98 % hodinu neroste, bere se kalibrace jako hotova - jinak by kazdy dalsi den byl
    // kalibracni a prodej by stal porad.
    if (st.calTopUp) {
        if (st.calTopMax == null || st.soc > st.calTopMax) { st.calTopMax = st.soc; st.calTopMaxAt = Date.now(); }
        else if (st.soc >= 98 && Date.now() - st.calTopMaxAt >= 3600000) {
            node.warn('Kalibrace: SOC ' + st.soc + ' % se hodinu nezvysil - BMS dal nepusti, kalibrace hotova.');
