if (!calMode) { st.calTopUp = false; st.calDeficitSince = null; st.calTopMax = null; }

// --- 2) kalibracni den ze slunce (posledni 4 dny pred limitem a dny cekani na lepsi den) ------
// Rozhoduje se jen rano: odpoledne uz by slunce na doplneni nestacilo a vyhlaseni by jen zbytecne
// zastavilo prodej. Jednou vyhlaseny den plati do 100 % nebo do 'solarDayUntil'.
if (st.calSolarDay && st.calSolarDay !== todayIso) st.calSolarDay = null;
if (!calMode && !st.calSolarDay && !plna && !hotovoDnes && daysSince >= solarFrom
