    text = 'neprodava se, prebytek jde do baterie; dobiti ze site mezi ' + hm(earliest) + ' a '
         + hm(latest) + chybi;
} else if (calMode) {
    text = 'neprodava se, prebytek jde do baterie; od ' + hm(latest) + ' dobiti ze site pri '
         + fromSoc + ' %' + (naplanovano ? ', jinak kalibracni den ' + den(naplanovano.iso) : '') + chybi;
