         + (ps.jas != null ? Math.round(ps.jas * 100) : '?') + ' %)';
} else if (naplanovano) {
    text = 'baterie nebyla plna ' + dny + ' dni - kalibracni den naplanovan na ' + den(naplanovano.iso)
