    text = 'naposledy 100 % ' + kdy + ' - ceka na slunecny den, kalibracni den nejdriv ' + den(dueIso);
} else {
    text = 'naposledy 100 % ' + kdy + ' (' + dm(cal.lastFullSocDate) + '); ze slunce od '
         + dm(plusDny(cal.lastFullSocDate, solarFrom)) + ', kalibracni den nejdriv ' + dm(dueIso);
}
