global.set('state', st);
node.status({ fill: (calMode || solarActive) ? 'yellow' : 'green', shape: 'dot',
              text: 'dny od 100%: ' + dny + (st.calTopUpActive ? ' - dobiji ze site'
                    : (calDay ? ' - kalibracni den' : (calMode ? ' - kalibracni rezim (neprodava se)' : '')))
                    + (solarActive ? ' - kalibracni den ze slunce' : '')
                    + (naplanovano ? ' - naplanovano ' + naplanovano.iso : '') });
return [{ payload: { text: text, daysSinceFull: daysSince, calDay: calMode || solarActive,
                     label: (calDay || solarActive) ? 'Den kalibrace baterie' : 'Kalibrace baterie - prodej vypnuty',
                     topUp: st.calTopUpActive, planned: naplanovano ? naplanovano.iso : null },
          topic: 'calibration-status' },
        zapis ? { filename: '/data/home/nodered/.node-red/fve-flow-data/calibration-state.json', payload: JSON.stringify(cal, null, 2), topic: 'write-calibration' } : null];

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

var cfg = fveCfg();   // platny profil (leto/zima) + spolecne hodnoty
var st = global.get('state') || {};
var now = fveNow();

var nominalW = (cfg.nominalMaxFeedInPowerKW || 0) * 1000;
var capFactor = (st.voltageCapFactor != null) ? st.voltageCapFactor : 1;
var cap = capFactor * nominalW;
var surplus = Math.max(0, st.surplusPowerW || 0);

// --- Mechanismus C: ranni odklad nabijeni ---------------------------------------------------
// Vse se vyhodnocuje TADY, nahore, at je to na jednom miste a nic se nepouzije driv, nez vznikne.
var md = cfg.morningDeferral || { enabled: false };
// V ZIME se ranni odklad neuplatnuje. Jde proti smyslu zimniho rezimu: v zime se baterie dobiji,
// aby vecer nechybela energie, takze odkladat ranni nabijeni je presne naopak. Zaroven tim odpada
// jakykoli prekryv s nocnim dobijenim (okna 05:00-11:00 a 22:00-07:00 se casove protinaji).
// Neni to parametr - v zime nema tenhle mechanismus rozumne pouziti.
var mdWinterOff = (fveSeason() === 'winter');
var mdInWindow = !!md.enabled && !mdWinterOff && fveInWindow(now.hm, md.from, md.to);
var mdSocOk = (st.soc != null && st.soc >= md.socThreshold);

// Cena: pevny prah je jen PODLAHA, k tomu musi byt cena v horni ctvrtine RANA. Pevne cislo samo
// o sobe nestaci - na drahem dni ho vycisti kazda ctvrthodina okna, na levnem zadna. Stejna uvaha
// jako u fveIsExpensiveNow u mechanismu A. fveMorningPrice() vraci null, kdyz nejsou spotova data;
// pak plati jen podlaha.
// Vse podle PRODEJNI ceny (viz fveMorningPrice) - odklad energii prodava, ne kupuje.
var mdFloorOk = (st.currentSellPrice != null && st.currentSellPrice >= md.priceThreshold);
var mdPrice = fveMorningPrice();
var mdRelOk = (mdPrice == null) ? true : mdPrice.ok;
// Pojistka: pod "Min. cenou pro export" se do site neposila nic ani mechanismem A, ani jako
// "jen prebytek" - odklad nesmi byt vyjimka. Jinak by pri spatne nastavene podlaze odklad
// dodaval treba i pri zaporne cene.
var mdExportOk = (st.currentSellPrice != null && st.currentSellPrice >= cfg.exportPriceThreshold);

// Pocasova brzda: kdyz ma byt dnes seredno, nema smysl ranni prebytek posilat do site - baterie
