// suoupatkem (0 % = pocasi se neresi, coz je vychozi stav a puvodni chovani).
// Index jasnosti pocita n_predict; je sezonne invariantni, viz komentar tam.
var mdMinClear = (md.minClearnessPercent != null) ? md.minClearnessPercent : 0;
var mdClear = (st.pvClearnessToday != null) ? st.pvClearnessToday * 100 : null;
// Kdyz predpoved chybi (restart Node-RED, vypadek site), brzda NEBRZDI. Fail-closed by znamenalo,
// ze se C po kazdem restartu tise vypne az do nejblizsiho fetche v 05:00; takhle je aspon videt
// ve stavovem radku na Prehledu, ze se rozhoduje bez predpovedi.
var mdWeatherOk = (mdMinClear <= 0) || (mdClear == null) || (mdClear >= mdMinClear);

var mdGo = mdInWindow && mdSocOk && mdFloorOk && mdRelOk && mdExportOk && mdWeatherOk;

// Kalibracni den - ze slunce i planovany (vyhlasuje cal_eval). Do 100 % se nesmi nic z toho, co
// baterii brani v nabiti: C drzi nabijeci proud, A posila prebytek do site nebo z baterie prodava,
// B z ni prodava. Nabijeni ze site (nutne/cilove SOC) ma prednost - je to levny nakup, ktery
