var calSolar = (st.calSolarActive === true) && !st.nightChargeActive;
if (calSolar) mdGo = false;
// Pod nutnym SOC (nebo kdyz prave bezi naplanovane nabijeni ze site) se odklad nespousti - drzel by
// nabijeci proud a prebil by nabijeni. Nastane jen pri prahu odkladu nastavenem POD nutnym SOC.
var mdMinSocOff = (st.nightChargeNeeded === true || st.nightChargeActive === true);
