// Stav pro radek na Prehledu. Slozeny text se sklada az v d_overview_extra, tady jen data.
st.mdStatus = {
    enabled: !!md.enabled, winterOff: mdWinterOff, inWindow: mdInWindow, from: md.from, to: md.to,
    socOk: mdSocOk, floorOk: mdFloorOk, relOk: mdRelOk, exportOk: mdExportOk, weatherOk: mdWeatherOk,
    priceFloor: md.priceThreshold, exportFloor: cfg.exportPriceThreshold,
    clearness: mdClear, minClearness: mdMinClear, haveForecast: (mdClear != null),
    priceFixed: !!(mdPrice && mdPrice.fixed),
    quartile: mdPrice ? mdPrice.quartile : null,
    windowsPassing: mdPrice ? mdPrice.pocetOken : null,
    windowsTotal: mdPrice ? mdPrice.celkemOken : null,
    calSolarOff: calSolar,
    minSocOff: mdMinSocOff,
    active: mdGo
};

// Plan mechanismu B je klicovany absolutnim datem (YYYY-MM-DD:ctvrthodina), aby fungovala
// i zitrejsi okna - drivejsi klicovani pres dayOffset znamenalo, ze zitrejsi okna nikdy nenastala.
var ebPlan = global.get('exportBPlan') || { chosenKey: [] };
var nowIdx = Math.floor(now.minutesOfDay / 15);
var exportBActive = ebPlan.chosenKey.indexOf(now.iso + ':' + nowIdx) !== -1;

// Kap. 5B: "% k obchodovani" se prodava, zbytek kapacity je nedotknutelny pro domacnost.
// Pod hranici rezervy se prodej z baterie zastavi.
var reservePct = (cfg.batteryReservePercent != null) ? cfg.batteryReservePercent : 0;
var batteryAboveReserve = (st.soc != null && st.soc > Math.max(reservePct, st.minSocFloor || 0));

// --- Klidovy setpoint -----------------------------------------------------------------------
// Hodnota, na kterou se regulace vraci, kdyz zadny mechanismus nezasahuje. Victron ESS ma
// tovarne +50 W (mirny odber ze site), aby se elektromer nikdy nedostal do pretoku. Kdyz chce
// uzivatel naopak vyloucit odber, nastavi zapornou hodnotu (napr. -50 W) a system drzi slaby
// trvaly pretok. Nastavuje se na strance Rezimy.
// V zime byva vhodna jina hodnota nez v lete (vyssi spotreba domu, mensi ochota pousteti
// energii do site), proto ma zima vlastni pole.
