var idleSrc = cfg.idleSetpointW;
var idleW = (typeof idleSrc === 'number') ? idleSrc : 0;
// Zaporny klidovy setpoint se bere z baterie, proto se na nej vztahuje rezerva pro domacnost -
// bez toho by baterii pomalu vysal az pod rezervu (pri -50 W jde o 1,2 kWh za den).
if (idleW < 0 && !batteryAboveReserve) idleW = 0;
// V kalibracni den (i ze slunce) je klidovy setpoint 0 - zaporny by trvale bral z baterie.
if (st.calSolarActive === true || st.calModeActive === true) idleW = 0;

// --- Mechanismus A (kap. 5A) - prodej i Z BATERIE, dno = "Prah SOC pro export" --------------
// Puvodni zadani resilo jen okamzity prebytek vyroby (setpoint = -min(prebytek, strop)), takze
// pri plne baterii a vysoke cene se vecer neprodalo NIC - prebytek je v tu dobu nula a na
// baterii sahal jedine planovac (mechanismus B) ve svych oknech.
// Nove: prah SOC slouzi zaroven jako spousteci podminka i jako DNO vybijeni. Nad nim se prodava
// plnym povolenym vykonem; zaporny AcPowerSetPoint si strídač pokryje nejdriv z FVE a zbytek
// dobere z baterie, takze se nic nedopocitava rucne.
var A_SOC_HYST = 2;                        // % SOC - bez hystereze by to na hrane prahu cvakalo
// Dnem je i "Nutne SOC" platneho profilu (st.minSocFloor z n_decide) - A pod nej nikdy neprodava.
var aFloor = Math.max(cfg.exportSocThreshold || 0, reservePct, st.minSocFloor || 0);   // nikdy pod rezervu domacnosti
var aPriceOk = (st.currentSellPrice != null && st.currentSellPrice >= cfg.exportPriceThreshold);
// POZOR na rozsah teto podminky: horni kvartil se uplatnuje JEN na vybijeni baterie, ne na export
// prebytku. Prebytek pri plne baterii nema kam jit, takze prodat ho za jakoukoli cenu nad prahem
// je vzdy lepsi nez ho uskrtit - kdyby kvartil platil i na nej, poledni vyroba by se pri drahem
// dnu zahazovala. Vybijeni baterie je naopak nakup/prodej: bez kvartilu by se v den, kdy je nad
// fixnim prahem kazda ctvrthodina, baterie vyprodala uz v noci a rano se kupovala zpatky draz
// (a v zime by se navic nikdy nedostalo na nocni dobijeni).
// fveIsExpensiveNow() vraci null, kdyz spotova data nejsou - pak plati jen fixni prah, stejna
// filozofie jako u fixnich cen v t_eval.
var aExpensive = fveIsExpensiveNow();
var aDeepGate = aPriceOk && (aExpensive !== false);


// POZOR NA PORADI: obe podminky nize musi byt deklarovane PRED latchem aDeep, ktery je pouziva.
// Drive stály az za nim - 'var' se sice vyhoistuje, takze to nespadlo, ale v okamziku pouziti mely
// hodnotu undefined (= nepravda) a obe pojistky se tedy NIKDY neuplatnily. Dusledek: v zime pri
// vypnutem obchodovani i v zimni noci pod cilovym SOC mechanismus A dal vybijel baterii plnym
// vykonem, jakmile cena spadla do horniho kvartilu. Regresni test to nechytil, protoze zimni
// pripady bezely na ctvrthodine pod kvartilem, kde je aDeepGate stejne nepravdive.

// Drivejsi vypinac "Obchodovat i v zime" od 0.9.037 nahradil "Nikdy nevybijet baterii do site"
// v zimnim profilu (neverDischarge nize) - dela totez a pri prechodu se nastaveni prevede samo.

// V zimni noci pod cilovym SOC se baterie nevybiji - viz st.nightChargeNeeded v n_decide.
// Diky tomu nema "Prah SOC pro export" na zimni nabijeni zadny vliv: driv pri nizkem prahu
// zustaval mechanismus A nabuzeny a prodaval prave nakoupenou energii.
var nightChargeNeeded = (st.nightChargeNeeded === true);

// Vypinac "Nikdy nevybijet baterii do site" (stranka Rezimy, skupina Baterie). Nastaveni
// "% k obchodovani" na nulu vypne jen planovac (B) - mechanismus A je na nem nezavisly a ridi se
// prahem SOC, takze baterii vybijel dal. Tenhle prepinac zastavi VSECHNY vetve, ktere posilaji do
// site vic nez zrovna merený prebytek vyroby.
// Klidoveho setpointu se ZAMERNE netyka - ten si uzivatel nastavuje samostatne a je to jeho volba.
var neverDischarge = (cfg.neverDischargeToGrid === true);

var aDeep = (st.exportADeep === true);     // latch: uz vybijime baterii, ne jen prebytek
if (st.soc == null || !aDeepGate || nightChargeNeeded || neverDischarge) {
    aDeep = false;                         // cena spadla pod prah / mimo spicku -> okamzity stop
} else if (!aDeep && st.soc >= aFloor + A_SOC_HYST) {
    aDeep = true;
} else if (aDeep && st.soc <= aFloor) {
    aDeep = false;                         // dojeli jsme na dno prahu
}
st.exportADeep = aDeep;
var aActive = aPriceOk && (st.soc != null && st.soc >= aFloor);

// --- Plna baterie: prodavej, kdyz je cena nad prahem ----------------------------------------
// Nad hranici "plna baterie" se neceka na horni kvartil ani na mereny prebytek a jede se plnym
// povolenym vykonem, jakmile je cena nad prahem pro export. Dva duvody, oba overene v provozu:
//
//  1) Plna baterie nema kam energii ulozit, takze regulator vyroby FVE uskrti na uroven spotreby
//     domu. Mereny prebytek je pak NULA - jenze presne podle nej se rozhoduje, kolik exportovat.
//     Vznikne zablokovany kruh: neexportuje se, protoze neni prebytek, a prebytek neni, protoze
//     se neexportuje. Rucni zaporny setpoint ho rozbije a FVE se hned rozbehne.
//  2) Cekat na horni kvartil nema pri plne baterii smysl - kvartil chrani ULOZENOU energii pred
//     vyprodanim v prumerne hodine, ale plna baterie zadnou dalsi energii neprijme. Drive se
//     proto stavalo, ze system stal na 100 % SOC pri slusne cene a nedelal nic.
//
// Vybijeni je omezene hysterezi: jakmile SOC klesne o A_FULL_HYST pod hranici, vetev se pusti
// a rizeni prebira bezny export prebytku. Z baterie se tak najednou odebere jen tenhle uzky pas.
var A_FULL_HYST = 3;                       // % SOC, o kolik smi SOC klesnout, nez se vetev pusti
var fullSoc = (cfg.batteryFullSocPercent != null) ? cfg.batteryFullSocPercent : 97;
var wasUnlock = (st.aUnlockActive === true);
var socFull = (st.soc != null) && (st.soc >= (wasUnlock ? fullSoc - A_FULL_HYST : fullSoc));
// (Do 0.9.036 tu byla vyjimka pro vypnute zimni obchodovani; to od 0.9.037 resi "Nikdy nevybijet"
// v zimnim profilu, ktery mechanismus A odstavi cely.)
var aUnlock = aActive && !aDeep && socFull && !nightChargeNeeded;
st.aUnlockActive = aUnlock;

// Nabijeci vykon je SAMOSTATNY parametr, ne stejny jako pretok. Do site smi tect jen tolik,
// kolik povoli distributor (casto jednotky kW), ale odebirat lze az po hlavni jistic, coz byva
// vyrazne vic. Zaloha na 'nominalMaxFeedInPowerKW' je kvuli starsimu ulozenemu configu.
// POZOR: capFactor (napetova ochrana) se na nabijeni zamerne NEuplatnuje - vysoke napeti v siti
// se resi omezenim exportu, odber ho naopak snizuje.
var chargeKW = (cfg.maxChargePowerKW != null) ? cfg.maxChargePowerKW : (cfg.nominalMaxFeedInPowerKW || 0);
var chargeW = chargeKW * 1000;
var setpointW = 0;
var reason = 'zadny-zasah';
var forceEvenManual = false;
// Zamer exportovat drzime jako priznak, ne porovnanim retezcu 'reason' - pri pridani noveho
// duvodu se pri porovnavani retezcu tise rozbil strop MaxFeedInPower.
var exportIntended = false;

// Rozhodovani bezi VZDY, i v manualnim rezimu - v manualu se jen nezapisuje na dbus (viz nize).
// Drive se v manualu preskocil cely blok, takze widget "Stav dodavky/nabijeni" hlasil natvrdo
// 'zadny-zasah (0 W)' a uzivatel nevidel ani doporuceni, ani realny tok do site.
if (st.calTopUpActive === true) {
    // Kalibracni den, odpoledni dobiti ze site do 100 % - bez ohledu na cenu (jde jen o zbytek,
    // ktery nedodalo slunce). Plati i v Manualu, stejne jako drivejsi kalibrace ze site.
    setpointW = chargeW;
    reason = 'kalibrace-dobiti';
    forceEvenManual = true;
} else {
    if (calSolar) {
        // Kalibracni den: setpoint klidovy (doplni blok nize), zadny limit nabijeciho proudu
        // (mdGo je vypnute), takze menic nabiji baterii vsim, co dum nespotrebuje.
        // Strop a pretok prebytku se pri cene nad prahem NECHAVAJI OTEVRENE. Neni to v rozporu:
        // setpoint nic nevytlacuje, takze ven jde jen to, co baterie nepobere - typicky ke konci,
        // kdy BMS stahne nabijeci proud. Bez toho by se v te fazi FVE zbytecne skrtila.
        // Rozdil proti A-prebytku: ten prikazoval setpoint -prebytek, takze baterie nedostala nic.
        setpointW = 0;
        reason = (st.calDayActive === true) ? 'kalibracni-den'
               : (st.calModeActive === true) ? 'kalibrace-cekani' : 'kalibrace-slunce';
        exportIntended = (st.currentSellPrice != null && st.currentSellPrice >= cfg.exportPriceThreshold);
    } else if (mdGo) {
        // Princip C: v okne se baterie NENABIJI ani NEVYBIJI do site a nadvyroba jde ven.
        // Deje se to tremi LIMITY, ne prikazem:
        //   MaxChargeCurrent = mdChargeA  -> baterie se (skoro) nenabiji
        //   AcPowerSetPoint  = klidovy    -> nic se z baterie nevytlacuje
        //   MaxFeedInPower   = plny strop -> menic posle ven, co zbyde
        // Drive se tu prikazoval setpoint -min(prebytek, strop). Fungovalo to, ale zaviselo to na
        // presnosti a zpozdeni mereneho prebytku: kdyz vyroba spadla driv, nez se to zmerilo,
        // prikaz uz platil a rozdil se bral z baterie. Limit tuhle tridu chyb nema.
        setpointW = 0;              // klidovou hodnotu doplni blok nize
        reason = 'ranni-odklad';
        exportIntended = true;
    } else if (exportBActive && batteryAboveReserve && !nightChargeNeeded
               && !neverDischarge) {
        setpointW = -cap;
        reason = 'prodej-z-baterie';
        exportIntended = true;
    } else if (st.nightChargeActive) {
        // Nad mechanismem A zamerne: nocni dobijeni je PLANOVANY zasah (aktivni jen v naplanovane
        // ctvrthodine a jen pod cilovym SOC), zatimco A je oportunni. Kdyz byl nizky "Prah SOC pro
        // export", zustaval A nabuzeny celou noc, uzemnil vetev nize a stav 'A-ceka-na-prebytek'
        // blokoval nabijeni, aniz by sam cokoli delal - baterie se pak v zime nedobila vubec.
        // V drahych hodinach k zablokovani nedojde: ty se do planu nejlevnejsich oken nedostanou.
        setpointW = chargeW;
        reason = 'nabijeni-ze-site';
    } else if (aActive && !neverDischarge) {
        // Nad prahem + hysterezi jedeme plny vykon (i z baterie), na samotnem prahu uz jen
        // prebytek vyroby - to je presne puvodni chovani, takze se pod prah nikdy nedostaneme.
        var aWantW = (aDeep || aUnlock) ? cap : Math.min(surplus, cap);
        setpointW = -aWantW;
        reason = aDeep ? 'prodej-A-z-baterie'
               : aUnlock ? 'prodej-A-plna-baterie'
               : (aWantW > 0 ? 'prodej-A-prebytek' : 'A-ceka-na-prebytek');
        // exportIntended zustava true i pri nulovem prebytku - strop MaxFeedInPower musi byt
        // otevreny dopredu, jinak by prebytek cekal na dalsi 15s tik, nez se limit zvedne.
        exportIntended = true;
    }
}

// Klidovy setpoint se uplatni dvema zpusoby:
//  - kdyz nezasahuje nic, je to primo prikazana hodnota,
//  - kdyz uz exportujeme, drzi aspon svuj pretok. To je potreba hlavne pro stav
//    'A-ceka-na-prebytek': bez toho by kazdy vypadek prebytku vratil odber ze site.
// Na nabijeci vetve (kladny setpoint) se nevztahuje - tam je nadbytecny.
if (reason === 'zadny-zasah') {
    setpointW = idleW;
    if (idleW !== 0) reason = 'klidovy-setpoint';
} else if (idleW < 0 && setpointW <= 0) {
    setpointW = Math.min(setpointW, idleW);
}

// --- Vypinac "Nikdy nevybijet baterii do site" ----------------------------------------------
// Mechanismy A i B jsou odstavene vyse. Zbyva jedina vec, kterou je potreba udelat aktivne:
// DRZET STROP OTEVRENY. Setpoint zustava na klidove hodnote, takze se baterie o nic nezada -
// a otevreny MaxFeedInPower necha menic poslat do site to, co sam vyhodnoti jako prebytek FVE.
//
// Proc zrovna takhle: setpoint je jedina paka, ktera NEUMI rozlisit "posli prebytek" od "vybij
// baterii" - rozhoduje jen jeho velikost proti okamzite vyrobe. Kdyz prikazes vic, nez panely
// davaji, zbytek prijde z baterie. Presne tim drive protekala vetev 'prodej-A-plna-baterie':
// pri vyrobe 800 W prikazovala -4000 W a rozdil brala z baterie, dokud SOC neklesl pod hysterezi.
// MaxFeedInPower tohle rozlisit umi, protoze je to strop, ne prikaz.
//
// Podminka: v GX musi byt zapnute "Feed-in excess DC-coupled PV" (/Settings/CGwacs/
// OvervoltageFeedIn). Bez nej menic pretok nepusti a do site by neslo nic.
// Cenova podminka tu MUSI byt. Kdyz vypinac odstavi mechanismus A, odstavi s nim i jeho kontrolu
// 'aPriceOk' - a otevreny strop by pak pustil prebytek do site i pri ZAPORNE cene, tedy bys za
// export platil. Pouziva se stejny prah jako pro mechanismus A ("Min. cena pro export"), takze
// zadny novy parametr: kdo chce prodavat jen nad nulou, da ho na 0.
// Horni kvartil se tu ZAMERNE neuplatnuje - ten chrani ulozenou energii pred vyprodanim
// v prumerne hodine, jenze tady se zadna ulozena energie neprodava. Prebytek nema kam jit,
// takze kazda cena nad prahem je lepsi nez ho uskrtit. Stejna asymetrie jako u mechanismu A.
if (neverDischarge && (reason === 'zadny-zasah' || reason === 'klidovy-setpoint')) {
    var prebytekCenaOk = (st.currentSellPrice != null
                          && st.currentSellPrice >= cfg.exportPriceThreshold);
    if (prebytekCenaOk) {
        exportIntended = true;                   // strop na plny povoleny pretok
        reason = 'jen-prebytek-FVE';
    } else {
        // Strop zustava nula (nebo velikost zaporneho klidoveho pretoku), takze nic nepotece.
        reason = 'jen-prebytek-pod-prahem';
    }
}

// MaxFeedInPower je STROP, ne prikaz - pokud ho necháme na nominalu i kdyz exportovat nechceme,
// pretece do site prebytek FVE bez ohledu na prahy SOC/ceny (kap. 5A). Proto 0, kdyz se neexportuje.
// POZOR: pri zapornem klidovem setpointu nesmi byt strop nula, jinak by Victron zadany slaby
// pretok nepustil a hodnota by se tvarila nastavena, ale nic by nedelala. Strop je pak presne
// tak velky, jak velky je klidovy pretok.
var feedInLimitW = exportIntended ? Math.round(cap)
                 : (setpointW < 0 ? Math.round(-setpointW) : 0);

// --- Limit nabijeciho proudu (mechanismus C) -------------------------------------------------
// -1 znamena "bez limitu" (viz dvcc.py: 'if user_max_charge_current < 0: ... = None').
// DVCC bere MINIMUM z tohoto limitu a limitu, ktery hlasi BMS, takze se s baterii nepereme -
// kdyz BMS stahne proud niz (studena baterie, blizici se plne nabiti), vyhraje BMS.
// POZOR: je to globalni trvale nastaveni GX. Drzime ho jen po dobu okna a jinak vracime -1,
// aby po padu Node-RED nezustala baterie zaskrcena. Prvni tik po startu zapise vzdy (force nize).
var mdChargeA = (md.maxChargeCurrentA != null) ? md.maxChargeCurrentA : 5;
var chargeLimitA = mdGo ? mdChargeA : -1;

// --- Povoleni pretoku prebytku z DC-coupled PV ----------------------------------------------
// 1 = menic smi poslat prebytek z MPPT do site, 0 = neposle (a MPPT se tim uskrti).
//
// PROC to nestaci resit stropem MaxFeedInPower: u DC-coupled PV se ten strop prokazatelne
// prekracuje. Kdyz je pretok prebytku povoleny, prestane platit i omezeni nabijeciho proudu
// z DVCC a MPPT jede na plny vykon, aby se pretok maximalizoval - regulace stropem to nestiha
// a do site odejdou kilowatty i pri stropu v desitkach wattu. Proto se pri nezajmu o export
// rovnou zakaze VYROBA prebytku, misto abychom ho zkouseli zadrzet limitem.
//
// Rozhoduje stejny priznak jako strop, takze se obe hodnoty nemuzou rozejit.
var feedInEnabled = exportIntended ? 1 : 0;

// V manualu se rozhodnuti jen zobrazuje jako doporuceni, nezapisuje se. Priznak potrebuje
// i statistika: bez nej by se do denniho rozpoctu mechanismu B zapocital i export, ktery si
// uzivatel nastavil rucne (planovac by pak zbytecne skrtal okna).
var essCommanded = (cfg.mode !== 'manual') || forceEvenManual;

st.essCommanded = essCommanded;
st.exportReason = reason;
global.set('state', st);

node.status({ fill: !essCommanded ? 'grey' : (setpointW !== 0 ? 'blue' : 'green'), shape: 'dot',
               text: (essCommanded ? '' : 'MANUAL, doporuceni: ') + reason + ' ('
                     + Math.round(setpointW) + ' W, limit ' + feedInLimitW + ' W)' });

// statusText se sklada uz tady - v JSONata by pri necekane hodnote (NaN) vyhodil vyjimku
// a Dashboard by pak zobrazil cely objekt jako "[object Object]".
var spRounded = Math.round(setpointW);

// SKUTECNY tok na pripojce (zaporny gridPowerW = dodavka do site, kladny = odber). Prikazany
// setpoint sam o sobe nestaci: v manualu ho regulace vubec nezapisuje a i v automatu se muze
// od skutecnosti lisit (baterie nestiha, menic omezuje, hodnotu prepsal nekdo v GUI).
var gridW = (typeof st.gridPowerW === 'number') ? Math.round(st.gridPowerW) : null;

// Zminka o zakazanem pretoku je jen v tom stavu, kdy neco vysvetluje - tedy kdyz uzivatel hleda,
// proc se neprodava. Jinak by radek zbytecne narostl.
var statusText = (essCommanded ? '' : 'MANUAL, doporuceni: ')
               + reason + ' (' + (isFinite(spRounded) ? spRounded : '?') + ' W, strop '
               + (isFinite(feedInLimitW) ? feedInLimitW : '?') + ' W'
               + (feedInEnabled ? '' : ', pretok FVE zakazan') + ')';
st.statusText = statusText;   // pro mobilni aplikaci (mob_build)
// Skutecny tok na pripojce (gridText) uz v radku neni - od 0.9.023 ho ukazuje grafika toku
// energie na Prehledu ("Odber ze site" / "Dodavka do site") a dublovalo se to.
var displayMsg = { payload: { reason: reason, setpointW: spRounded, capW: feedInLimitW,
                              mode: cfg.mode, commanded: essCommanded, gridPowerW: gridW,
                              statusText: statusText }, topic: 'export-status' };

if (!essCommanded) {
    // V manualu nezapisujeme nic - s jedinou vyjimkou: kdyz jsme neco z vlastni vule OMEZILI,
    // musime to uvolnit. Jinak by prepnuti do Manualu nechalo baterii zaskrcenou nebo pretok
    // zakazany a nikdo by nevedel proc. Uvolnujeme jen vlastni zasah, cizi nastaveni neprepisujeme.
    var uvolniLimit = (st.lastChargeLimitA != null && st.lastChargeLimitA >= 0);
    var uvolniPretok = (st.lastFeedInEnabled === 0);
    if (uvolniLimit || uvolniPretok) {
        if (uvolniLimit) st.lastChargeLimitA = -1;
        if (uvolniPretok) st.lastFeedInEnabled = 1;
        global.set('state', st);
        return [displayMsg, null, null,
                uvolniLimit ? { payload: -1, topic: 'maxchargecurrent' } : null,
                uvolniPretok ? { payload: 1, topic: 'feedinenabled' } : null];
    }
    return [displayMsg, null, null, null, null];
}

// Zapisovat na dbus jen pri zmene (jinak by slo o zapis kazdych 15 s), plus bezpecnostni
// resync jednou za 5 minut pro pripad, ze hodnotu prepsal nekdo zvenci (GUI, jiny flow).
var sp = Math.round(setpointW);
var RESYNC_MS = 5 * 60 * 1000;
var force = (st.lastEssWriteAt == null) || (Date.now() - st.lastEssWriteAt > RESYNC_MS);
var changed = (st.lastSetpointW !== sp) || (st.lastFeedInLimitW !== feedInLimitW)
           || (st.lastChargeLimitA !== chargeLimitA) || (st.lastFeedInEnabled !== feedInEnabled);
if (!changed && !force) {
    return [displayMsg, null, null, null, null];
}
st.lastSetpointW = sp;
st.lastFeedInLimitW = feedInLimitW;
st.lastChargeLimitA = chargeLimitA;
st.lastFeedInEnabled = feedInEnabled;
st.lastEssWriteAt = Date.now();
global.set('state', st);

return [displayMsg, { payload: sp, topic: 'setpoint' }, { payload: feedInLimitW, topic: 'maxfeedin' },
        { payload: chargeLimitA, topic: 'maxchargecurrent' },
        { payload: feedInEnabled, topic: 'feedinenabled' }];

var pid = global.get('portalId') || (global.get('config') || {}).vrmId;
if (!pid) { node.status({ fill: 'red', shape: 'ring', text: 'chybi VRM Portal ID - nezapisuje se' }); return null; }
if (typeof msg.payload !== 'number') return null;
node.status({ fill: 'blue', shape: 'dot', text: msg.payload + ' W' });
return { topic: 'W/' + pid + '/settings/0/Settings/CGwacs/AcPowerSetPoint',
         payload: { value: msg.payload } };

var pid = global.get('portalId') || (global.get('config') || {}).vrmId;
if (!pid) { node.status({ fill: 'red', shape: 'ring', text: 'chybi VRM Portal ID - nezapisuje se' }); return null; }
if (typeof msg.payload !== 'number') return null;
node.status({ fill: 'blue', shape: 'dot', text: msg.payload + ' W' });
return { topic: 'W/' + pid + '/settings/0/Settings/CGwacs/MaxFeedInPower',
         payload: { value: msg.payload } };

// Cesta je jinde nez u ESS parametru: /Settings/SystemSetup/, ne /Settings/CGwacs/.
// Hodnota je v AMPERECH, -1 = bez limitu. Uplatni se jen kdyz je v GX zapnute DVCC - bez nej
// dbus-systemcalc-py tuhle hodnotu ignoruje ('if not self.has_dvcc: return').
var pid = global.get('portalId') || (global.get('config') || {}).vrmId;
if (!pid) { node.status({ fill: 'red', shape: 'ring', text: 'chybi VRM Portal ID - nezapisuje se' }); return null; }
if (typeof msg.payload !== 'number') return null;
node.status({ fill: msg.payload >= 0 ? 'yellow' : 'green', shape: 'dot',
              text: msg.payload >= 0 ? ('limit ' + msg.payload + ' A') : 'bez limitu' });
return { topic: 'W/' + pid + '/settings/0/Settings/SystemSetup/MaxChargeCurrent',
         payload: { value: msg.payload } };

// 0 = neposilat prebytek z DC-coupled PV do site (MPPT se tim uskrti), 1 = posilat.
// Je to boolean, ne vykon, i kdyz sedi v CGwacs vedle ESS parametru.
var pid = global.get('portalId') || (global.get('config') || {}).vrmId;
if (!pid) { node.status({ fill: 'red', shape: 'ring', text: 'chybi VRM Portal ID - nezapisuje se' }); return null; }
if (typeof msg.payload !== 'number') return null;
node.status({ fill: msg.payload ? 'green' : 'yellow', shape: 'dot',
              text: msg.payload ? 'pretok FVE povolen' : 'pretok FVE ZAKAZAN' });
return { topic: 'W/' + pid + '/settings/0/Settings/CGwacs/OvervoltageFeedIn',
         payload: { value: msg.payload } };

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

var cfg = (global.get('config') || {}).relay1;
var st = global.get('state') || {};
var now = fveNow();
if (!cfg) return null;

var prev = !!st.relay1On;
