var id = global.get('portalId') || cfg.vrmId;
if (!id) { node.status({ fill: 'yellow', shape: 'ring', text: 'ceka na vrmId' }); return null; }

// Stari poslednich MQTT dat - server pak pozna rozdil mezi 'Node-RED bezi, ale nevidi Victron'
// a 'neozval se vubec'.
var mqttAgeS = st.lastMqttDataAt ? Math.round((Date.now() - st.lastMqttDataAt) / 1000) : null;

return { url: url, payload: {
    v: 1,
    id: id,
    name: cfg.installName || null,
    ver: global.get('version') || null,
    venus: global.get('venusVersion') || null,       // verze Venus OS (z MQTT)
    zona: fveZona ? fveZona().kod : null,            // trh (zona spotovych cen)
    mode: cfg.mode || null,                          // auto / manual
    tradePct: cfg.batteryTradingPercent,
    deferral: !!(md.enabled),
    season: fveSeason(),                             // skutecna sezona vcetne automatiky
    feedInKW: cfg.nominalMaxFeedInPowerKW,
    noSell: !!cfg.neverDischargeToGrid,
    soc: (st.soc == null ? null : st.soc),
    reason: st.exportReason || null,
    mqttOk: (mqttAgeS !== null && mqttAgeS < 90),
    mqttAgeS: mqttAgeS,
    capKWh: cfg.batteryCapacityKWh,
    kWp: cfg.pvSizeKWp
} };

// Heartbeat je diagnostika, ne rizeni. Kdyz server nebezi nebo je instalace bez internetu,
// nesmi to delat cervene hlasky v logu - proto senderr a tise spolknuta chyba.
// Priste to zkusi za 6 hodin.
var ok = (msg.statusCode === 200);
node.status({
    fill: ok ? 'green' : 'yellow',
    shape: ok ? 'dot' : 'ring',
    text: ok ? ('odeslano ' + new Date().toLocaleTimeString('cs-CZ'))
             : ('neodeslano (' + (msg.statusCode || 'bez spojeni') + ')')
});
return null;

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

var stat = global.get('configStatic') || {};
var url = stat.mobile && stat.mobile.url;
if (!url) { node.status({ fill: 'grey', shape: 'ring', text: 'vypnuto (bez URL)' }); return null; }
var cfg = fveCfg();
var st = global.get('state') || {};
var mob = global.get('mobile') || {};
var id = global.get('portalId') || cfg.vrmId;
if (!id) { node.status({ fill: 'yellow', shape: 'ring', text: 'ceka na vrmId' }); return null; }

var mqttAgeS = st.lastMqttDataAt ? Math.round((Date.now() - st.lastMqttDataAt) / 1000) : null;
function num(x) { return (typeof x === 'number' && isFinite(x)) ? Math.round(x * 100) / 100 : null; }
var data = {
    soc: num(st.soc), pv: num(st.pvPowerW), cons: num(st.consumptionPowerW),
    sur: num(st.surplusPowerW), grid: num(st.gridPowerW), bat: num(st.batteryPowerW),
    kWp: cfg.pvSizeKWp || 0, capKWh: cfg.batteryCapacityKWh || null,
    scaleW: Math.max((cfg.maxChargePowerKW || 0) * 1000, (cfg.pvSizeKWp || 0) * 1000),
    stav: (global.get('fveKody') || function (x) { return x; })(st.statusText) || null,
    rezim: cfg.mode || null, sezona: fveSeason(),
    plan: st.planText || null, predpoved: st.forecastText || null, odklad: st.mdText || null,
    kalibrace: st.calText || null,
    venus: global.get('venusVersion') || null,   // verze Venus OS - v paticce aplikace
    // Energie dnes z pocitadel (stejne jako na Prehledu dashboardu): dodano, odebrano, vyroba FVE (kWh)
    energie: st.energyToday ? { dodano: num(st.energyToday.exportKWh), odebrano: num(st.energyToday.importKWh),
                                fve: num(st.energyToday.pvKWh) } : null,
    jazyk: 'cs',   // jazyk textu (plan, stav...) - podle nej aplikace voli jazyk popisku; EN flow posila 'en'
    mena: global.get('fveMena') ? global.get('fveMena')().kod : 'CZK',   // CZK / EUR - jednotka cen v aplikaci
    nakup: num(st.currentBuyPrice), prodej: num(st.currentSellPrice), tarif: st.tariff || null,
    mqttOk: (mqttAgeS !== null && mqttAgeS < 90)
};
var rotate = !!mob.rotate;
node.status({ fill: 'blue', shape: 'dot', text: (mob.pushSecret ? 'odesilam' : 'registrace') + (rotate ? ' + novy klic' : '') });
return { url: url, payload: { v: 1, id: id, name: cfg.installName || null, ver: global.get('version') || null,
                              push: mob.pushSecret || null, rotate: rotate, data: data } };

// Stejne jako heartbeat: vypadek serveru nesmi delat cervene hlasky (senderr, tise).
var mob = global.get('mobile') || {};
if (msg.statusCode !== 200) {
    var proc = (msg.statusCode === 403) ? 'odmitnuto - server instalaci nezna tento klic (README-server: reset)'
             : ('neodeslano (' + (msg.statusCode || 'bez spojeni') + ')');
    node.status({ fill: msg.statusCode === 403 ? 'red' : 'yellow', shape: 'ring', text: proc });
    return null;
}
var odp = msg.payload;
if (typeof odp === 'string') { try { odp = JSON.parse(odp); } catch (e) { odp = {}; } }
odp = odp || {};
var zmena = false;
if (odp.pushSecret) { mob.pushSecret = odp.pushSecret; zmena = true; }
if (odp.viewKey) { mob.viewKey = odp.viewKey; mob.viewKeyAt = new Date().toISOString(); zmena = true; }
if (mob.rotate && odp.viewKey) { delete mob.rotate; }
node.status({ fill: 'green', shape: 'dot', text: 'odeslano ' + new Date().toLocaleTimeString('cs-CZ') });
if (!zmena) return null;
global.set('mobile', mob);
// Klice se ulozi do souboru a QR na strance Konfigurace se prekresli.
return [{ filename: '/data/home/nodered/.node-red/fve-flow-data/mobile-state.json', payload: JSON.stringify(mob, null, 2), topic: 'write-mobile' },
        { topic: 'mobile-changed' }];

var st = global.get('state') || {};
var cfg = global.get('config') || {};
// Meritko pruhu: vetsi z nabijeciho vykonu ze site a vykonu FVE - typicke maximum toku baterii.
var scaleW = Math.max((cfg.maxChargePowerKW || 0) * 1000, (cfg.pvSizeKWp || 0) * 1000);
return { payload: { soc: st.soc, batW: (typeof st.batteryPowerW === 'number') ? st.batteryPowerW : null,
                    cal: st.calText || null, scaleW: scaleW, capKWh: cfg.batteryCapacityKWh || null,
                    calDay: !!(st.calModeActive || st.calSolarActive),
                    calLabel: (st.calDayActive || (st.calSolarActive && !st.calModeActive))
                        ? 'Den kalibrace baterie' : 'Kalibrace baterie - prodej vypnuty' } };

var p = msg.payload || {};
var cfg = global.get('config') || {};
var st = global.get('state') || {};
// Tok na pripojce m_agg do zpravy 'measurements' nedava, je jen ve stavu.
return { payload: { pv: p.pvPowerW, cons: p.consumptionPowerW, sur: p.surplusPowerW,
                    grid: (typeof st.gridPowerW === 'number') ? st.gridPowerW : null,
                    kWp: cfg.pvSizeKWp || 0 } };

var c = context.get('v') || {};
var p = msg.payload || {};
// Mena podle zony trhu (Kc, EUR), u EUR 3 desetinna mista.
var M = (global.get('fveMena') || function () { return { text: 'Kc', des: 2 }; })();
function kc(x) { return (typeof x === 'number') ? x.toFixed(M.des).replace('.', ',') + ' ' + M.text + '/kWh' : null; }
switch (msg.topic) {
    case 'export-status':
        var fk = global.get('fveKody');
        c.stav = (fk ? fk(p.statusText) : p.statusText) || null;
        c.rezim = (p.mode === 'manual') ? 'Manual' : 'Automat';
        break;
    case 'tariff-price-status':
        // Pripisek zdroje jen u spotove ceny: (OTE) = zalozni zdroj, (fix) = spot chybi uplne.
        var pz = (p.zdroj === 'OTE') ? ' (OTE)' : (p.zdroj === 'fix' ? ' (fix - chybi spot)' : '');
        var kn = kc(p.buy), kp = kc(p.sell);
        c.nakup = (kn != null && p.spotBuy) ? kn + pz : kn;
        c.prodej = (kp != null && p.spotSell) ? kp + pz : kp;
        c.tarif = (p.tariff === 'low') ? 'nizky (NT)' : (p.tariff === 'high' ? 'vysoky (VT)' : null);
        break;
    case 'forecast':
        c.predpoved = p.text || null;
        break;
    case 'md-status':
        c.odklad = p.text || null;
        // Nadpis nese nastaveny prah jasnosti - drive ho ui-text dostaval pres ui_update.label.
        c.odkladLabel = (msg.ui_update && msg.ui_update.label) || null;
        break;
    case 'mqtt-status':
        c.mqtt = p.text || null;
        c.mqttOk = !!p.ok;
        break;
    default:
        return null;
}
context.set('v', c);
return [{ payload: c }, { payload: c }];

var fveNow = global.get('fveNow');
var fveInWindow = global.get('fveInWindow');
var fveIsCheapNow = global.get('fveIsCheapNow');
var fveIsExpensiveNow = global.get('fveIsExpensiveNow');
var fveNetBuy = global.get('fveNetBuy');
var fveNetSell = global.get('fveNetSell');
var fveSeason = global.get('fveSeason');
var fveMorningPrice = global.get('fveMorningPrice');
var fveCfg = global.get('fveCfg');
var fveNa96 = global.get('fveNa96');
var fveZona = global.get('fveZona');
var fveLokal = global.get('fveLokal');
// Pojistka: helpery vznikaji az v c_init. Kdyby nejaka vetev dobehla driv (napr. HTTP odpoved
// spot cen), volani fveNow() by shodilo uzel. Radeji tichy preskok - dalsi tik to dozene.
if (!fveNow) { node.warn('Helpery jeste nejsou pripravene (c_init nedobehl) - preskakuji tento cyklus.'); return null; }

var MENA = (global.get('fveMena') || function () { return { text: 'Kc' }; })().text;   // Kc / EUR podle zony
// Slozene texty se skladaji tady v JS, ne v JSONata - pri necekane hodnote (null, NaN) by
// JSONata vyhodila vyjimku a Dashboard by nechal payload beze zmeny, takze by widget ukazal
// '[object Object]'. Viz kap. 7 README.
var st = global.get('state') || {};

function kwh(x) { return (x == null) ? '?' : x.toFixed(1); }
function jas(x) { return (x == null) ? '?' : x.toFixed(2); }

// --- predpoved vyroby -----------------------------------------------------------------------
var maPred = (st.pvPredictionTodayKWh != null || st.pvClearnessToday != null);
var fText;
if (!maPred) {
    fText = 'zatim nenactena (stahuje se v 05:00 a 20:00)';
} else {
    fText = 'dnes ' + kwh(st.pvPredictionTodayKWh) + ' kWh (index jasnosti '
          + jas(st.pvClearnessToday) + ')';
    if (st.pvPredictionTomorrowKWh != null) {
        fText += ', zitra ' + kwh(st.pvPredictionTomorrowKWh) + ' kWh ('
               + jas(st.pvClearnessTomorrow) + ')';
    }
}

// --- stav mechanismu C ----------------------------------------------------------------------
var m = st.mdStatus;
var prah = (m && m.minClearness > 0) ? (Math.round(m.minClearness) + ' %') : 'nenastaven';
var label = 'Ranni odklad nabijeni (mechanismus C, nastaveny index jasnosti ' + prah + ')';

var cText;
if (!m) {
    cText = 'ceka na prvni vyhodnoceni';
} else if (!m.enabled) {
    cText = 'vypnuto';
} else if (m.winterOff) {
    cText = 'vypnuto - zimni rezim (odklad se v zime neuplatnuje)';
} else if (m.minSocOff && m.inWindow) {
    cText = 'vypnuto - baterie je pod nutnym SOC, nabiji se';
} else if (m.calSolarOff) {
    cText = 'vypnuto - dnes den kalibrace baterie (nabiji se na 100 %)';
} else if (!m.weatherOk) {
    cText = 'vypnuto pro spatnou predpoved (jasnost ' + Math.round(m.clearness)
          + ' % < prah ' + Math.round(m.minClearness) + ' %)';
} else {
    var kde = !m.inWindow ? 'ted mimo okno'
            : (!m.socOk ? 'ceka na SOC'
            : (!m.exportOk ? 'prodejni cena pod Min. prodejni cenou pri nadbytku (' + m.exportFloor + ' ' + MENA + ')'
            : (!m.floorOk ? 'prodejni cena pod cenou pro odklad (' + m.priceFloor + ' ' + MENA + ')'
            : (!m.relOk ? 'prodejni cena mimo nejdrazsi ctvrtinu rana' : 'PRAVE AKTIVNI'))));
    var plan = m.priceFixed
        ? 'fixni prodejni cena, nejdrazsi ctvrtina se neuplatnuje'
        : ((m.windowsTotal != null)
            ? ('vyhovuje ' + m.windowsPassing + ' z ' + m.windowsTotal + ' ctvrthodin okna')
            : 'bez spotovych dat, plati jen cena pro odklad');
    cText = 'zapnuto - okno ' + m.from + '-' + m.to + ', ' + plan + '; ' + kde;
    if (!m.haveForecast && m.minClearness > 0) {
        cText += ' | predpoved chybi, brzda neaktivni';
    }
}

// --- aktualni plan (druhy radek pod stavem dodavky) -----------------------------------------
// Prvni radek rika, co se deje TED. Tenhle rika, co je naplanovano dopredu: kolik ctvrthodin
// jeste dnes ceka planovac prodeje (mechanismus B), kdy je nejblizsi, kolik z denniho rozpoctu
// uz je prodano - a v zime totez pro nocni nabijeni.
var now = fveNow();
var nowIdx = Math.floor(now.minutesOfDay / 15);
function hm(idx) {
    var h = Math.floor(idx / 4), mi = (idx % 4) * 15;
    return (h < 10 ? '0' : '') + h + ':' + (mi < 10 ? '0' : '') + mi;
}

var eb = global.get('exportBPlan') || {};
var rozpocet = (typeof eb.reservedKWh === 'number' && eb.reservedKWh > 0)
    ? ', ' + (eb.soldKWh || 0).toFixed(1) + '/' + eb.reservedKWh.toFixed(1) + ' kWh' : '';
// Kdyz plan omezuje energie v baterii (ne rozpocet), musi to byt videt - jinak by "0 oken"
// pri volnem rozpoctu vypadalo jako chyba.
var omezSoc = (typeof eb.availKWh === 'number' && typeof eb.reservedKWh === 'number'
               && eb.availKWh < eb.reservedKWh - (eb.soldKWh || 0));
if (omezSoc) rozpocet += ' (v baterii nad ' + eb.floorPct + ' % jen ' + eb.availKWh.toFixed(1) + ' kWh)';
// Klic okna je "YYYY-MM-DD:ctvrthodina" - datum dvojtecku nema, takze split(':') staci.
var dnesB = (eb.chosenKey || [])
    .filter(function (k) { return k.indexOf(now.iso + ':') === 0; })
    .map(function (k) { return Number(k.split(':')[1]); })
    .filter(function (q) { return q >= nowIdx; })
    .sort(function (a, b) { return a - b; });
var bText;
if (!eb.generatedAt) {
    // Rozlisit "jeste se nepocitalo" od "spocitano, ale nic nevyslo" - jinak by radek po restartu
    // tvrdil, ze uz dnes zadne okno neni, coz by nebyla pravda.
    bText = 'prodej z baterie: plan se jeste nepocital';
} else if (dnesB.length) {
    bText = 'prodej z baterie: ' + dnesB.length + ' oken, nejbliz ' + hm(dnesB[0]) + rozpocet;
} else {
    bText = 'prodej z baterie: dnes uz zadne okno' + rozpocet;
}
// V den kalibrace A ani B neprodavaji, dokud baterie nedojde na 100 % - okna planu B se tedy
// uplatni az potom (typicky vecer).
if (dnesB.length && (st.calModeActive || st.calSolarActive)) bText += ' (az po kalibraci)';

var nb = global.get('nightChargePlan') || {};
var L = nb.levels;
var nText;
if (!L) {
    nText = 'nabijeni ze site: ' + (nb.note || 'neplanuje se');
} else {
    function ctvrt(n) { return n + (n === 1 ? ' ctvrthodina' : (n >= 2 && n <= 4) ? ' ctvrthodiny' : ' ctvrthodin'); }
    function cast(nazev, soc, kdy, need, pocet, prvni) {
        if (need <= 0) return nazev + ' ' + Math.round(soc) + ' % splneno';
        return nazev + ' ' + Math.round(soc) + ' % do ' + kdy + ' (' + ctvrt(pocet)
             + (prvni ? ', od ' + prvni : '') + ')';
    }
    // Nutne SOC i zaporna cena plati v lete i v zime, cilove (levne) SOC jen v zime.
    var casti = [];
    if (L.minSoc > 0) {
        casti.push(cast('nutne', L.minSoc, L.minBy, L.minNeedKWh, L.minSlots, L.minFirst)
            + (L.minShortKWh > 0 ? ' ⚠ nestihne se, chybi ' + L.minShortKWh.toFixed(1) + ' kWh' : ''));
    }
    if (L.tgt > L.minSoc) {
