            ? ('levne ' + Math.round(L.tgt) + ' %: zadna ctvrthodina pod ' + L.maxPrice + ' ' + MENA)
            : cast('levne', L.tgt, L.tgtBy, L.tgtNeedKWh, L.tgtSlots, L.tgtFirst));
    }
    if (L.negSlots) casti.push('zaporna cena: ' + ctvrt(L.negSlots) + ' od ' + L.negFirst);
    nText = 'nabijeni ze site: ' + (casti.length ? casti.join(', ') : 'nic potreba');
    if (L.fixFallbackSlots) nText += ' (chybi spotove ceny - pocita s fixni cenou)';
}

var planText = bText + ' | ' + nText;
// Texty pro mobilni aplikaci (mob_build) - skladaji se jen tady, at jsou v aplikaci stejne.
st.planText = planText;
st.forecastText = fText;
st.mdText = cText;
global.set('state', st);

// Na Prehledu dva radky (prodej / nabijeni), kazdy s vlastnim popiskem - uvodni "prodej z baterie: "
// a "nabijeni ze site: " jsou pak v popisku, ne v textu.
var B_PRE = 'prodej z baterie: ', N_PRE = 'nabijeni ze site: ';
