return [
    { payload: { text: planText, prodej: bezUvodu(bText, B_PRE), nabijeni: bezUvodu(nText, N_PRE) } },
    { payload: { text: fText }, topic: 'forecast' },
    { payload: { text: cText }, ui_update: { label: label }, topic: 'md-status' }
