var devices = msg.payload.devices || {};
var rows = Object.keys(devices).map(function (k) {
    return { zarizeni: k, onMinut: Math.round(devices[k].onSeconds / 60), pocetSepnuti: devices[k].onCount };
});
return { payload: rows };

var c = msg.payload || {};
var om = c.openMeteo || {};
function v(x) { return (x === undefined) ? null : x; }
return [
    { payload: v(c.installName) }, { payload: v(c.vrmId) },
    { payload: v(c.batteryCapacityKWh) }, { payload: v(c.pvSizeKWp) },
    { payload: v(om.latitude) }, { payload: v(om.longitude) }
];

var c = msg.payload || {};
var om = c.openMeteo || {};
var chybi = [];
if (!c.vrmId) chybi.push('VRM Portal ID');
if (!(c.batteryCapacityKWh > 0)) chybi.push('kapacita baterie');
if (!(c.pvSizeKWp > 0)) chybi.push('vykon FVE');
if (typeof om.latitude !== 'number' || typeof om.longitude !== 'number') chybi.push('souradnice');
if (!c.installName) chybi.push('nazev');
